QT_ISI(9,{"1042":["(Pemuka-pemuka dari kaum Syuaib yang menyombongkan diri berkata,) mereka yang sombong tidak mau beriman (\"Sesungguhnya kami akan mengusir kamu hai Syuaib dan orang-orang yang beriman bersamamu dari kota kami atau kamu kembali) sungguh mau kembali (kepada agama kami.\") yaitu din/agama kami. Di dalam pembicaraan ini yang dipakai dhamir jamak padahal pembicaranya hanya seorang yaitu Syuaib sendiri. Sebab Syuaib itu sama sekali bukan berada dalam agama mereka, lalu ia menjawab sebaliknya (Syuaib menjawab, \"Apakah) kami harus kembali kepada agamamu itu (kendatipun kami tidak menyukainya?\") Istifham/kata tanya di sini mengandung pengertian pengingkaran.",[["۞ قَالَ","Said"],["ٱلْمَلَأُ","the chiefs"],["ٱلَّذِينَ","(of) those who"],["ٱسْتَكْبَرُوا۟","were arrogant"],["مِن","among"],["قَوْمِهِۦ","his people"],["لَنُخْرِجَنَّكَ","We will surely drive you out"],["يَـٰشُعَيْبُ","O Shuaib"],["وَٱلَّذِينَ","And those who"],["ءَامَنُوا۟","(have) believed"],["مَعَكَ","with you"],["مِن","from"],["قَرْيَتِنَآ","our city"],["أَوْ","or"],["لَتَعُودُنَّ","you must return"],["فِى","to"],["مِلَّتِنَا ۚ","our religion"],["قَالَ","He said"],["أَوَلَوْ","Even if"],["كُنَّا","we are"],["كَـٰرِهِينَ","(the) ones who hate (it)"]]],"1043":["(Sungguh kami mengada-adakan kebohongan yang besar terhadap Allah jika kami kembali kepada agamamu sesudah Allah melepaskan kami daripadanya. Dan tidaklah patut) tidak pantas (bagi kami kembali kepadanya kecuali jika Allah Tuhan kami menghendaki) hal itu, yaitu menghinakan kami (Pengetahuan Tuhan kami meliputi segala sesuatu) yang di antaranya ialah Dia mengetahui keadaanku dan keadaanmu (Kepada Allah sajalah kami bertawakal. Ya Tuhan kami, berilah keputusan) ketentuan hukum (antara kami dan kaum kami dengan hak dan Engkaulah pemberi keputusan yang sebaik-baiknya) yakni hakim yang paling baik.",[["قَدِ","Verily"],["ٱفْتَرَيْنَا","we would have fabricated"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًا","a lie"],["إِنْ","if"],["عُدْنَا","we returned"],["فِى","in"],["مِلَّتِكُم","your religion"],["بَعْدَ","after"],["إِذْ","[when]"],["نَجَّىٰنَا","saved us"],["ٱللَّهُ","Allah"],["مِنْهَا ۚ","from it"],["وَمَا","And not"],["يَكُونُ","it is"],["لَنَآ","for us"],["أَن","that"],["نَّعُودَ","we return"],["فِيهَآ","in it"],["إِلَّآ","except"],["أَن","that"],["يَشَآءَ","wills"],["ٱللَّهُ","Allah "],["رَبُّنَا ۚ","our Lord"],["وَسِعَ","Encompasses"],["رَبُّنَا","(by) Our Lord"],["كُلَّ","every"],["شَىْءٍ","thing"],["عِلْمًا ۚ","(in) knowledge"],["عَلَى","Upon"],["ٱللَّهِ","Allah"],["تَوَكَّلْنَا ۚ","we put our trust"],["رَبَّنَا","Our Lord"],["ٱفْتَحْ","Decide"],["بَيْنَنَا","between us"],["وَبَيْنَ","and between"],["قَوْمِنَا","our people"],["بِٱلْحَقِّ","in truth"],["وَأَنتَ","and You"],["خَيْرُ","(are the) Best"],["ٱلْفَـٰتِحِينَ","(of) those who Decide"]]],"1044":["(Pemuka-pemuka kaum Syuaib yang kafir berkata,) sebagian mereka berkata kepada sebagian yang lain (\"Sesungguhnya jika) lam adalah untuk qasam atau sumpah (kamu mengikut Syuaib, tentu jika kamu berbuat demikian menjadi orang-orang yang merugi.\")",[["وَقَالَ","And said"],["ٱلْمَلَأُ","the chiefs"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved"],["مِن","among"],["قَوْمِهِۦ","his people"],["لَئِنِ","If"],["ٱتَّبَعْتُمْ","you follow"],["شُعَيْبًا","Shuaib"],["إِنَّكُمْ","indeed, you"],["إِذًۭا","then"],["لَّخَـٰسِرُونَ","(will be) certainly losers"]]],"1045":["(Kemudian mereka ditimpa gempa) gempa bumi yang dahsyat (maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka) mereka mati dalam keadaan bertekuk-lutut.",[["فَأَخَذَتْهُمُ","Then seized them"],["ٱلرَّجْفَةُ","the earthquake"],["فَأَصْبَحُوا۟","then they became"],["فِى","in"],["دَارِهِمْ","their home(s)"],["جَـٰثِمِينَ","fallen prone"]]],"1046":["(Yaitu orang-orang yang mendustakan Syuaib) menjadi mubtada dan khabarnya ialah (seolah-olah) dengan ditakhfifkan sedangkan isimnya dibuang, lengkapnya ialah: Seolah-olah mereka (mereka belum pernah berdiam) artinya mereka belum pernah tinggal (di kota itu) di rumah-rumah mereka sendiri (orang-orang yang mendustakan Syuaib mereka itulah orang-orang yang merugi) pengukuhan dengan mengulangi maushul dan lainnya merupakan jawaban terhadap perkataan mereka yang terdahulu.",[["ٱلَّذِينَ","Those who"],["كَذَّبُوا۟","denied"],["شُعَيْبًۭا","Shuaib"],["كَأَن","(became) as if"],["لَّمْ","not"],["يَغْنَوْا۟","they (had) lived"],["فِيهَا ۚ","therein"],["ٱلَّذِينَ","Those who"],["كَذَّبُوا۟","denied"],["شُعَيْبًۭا","Shuaib"],["كَانُوا۟","they were"],["هُمُ","them"],["ٱلْخَـٰسِرِينَ","the losers"]]],"1047":["(Maka Syuaib berpaling) yakni meninggalkan (mereka seraya berkata, \"Hai kaumku! Sesungguhnya aku telah menyampaikan amanat-amanah Tuhanku dan aku telah memberi nasihat kepadamu) akan tetapi kamu tidak juga mau beriman (Maka bagaimana aku akan bersedih hati) bersusah hati (terhadap orang-orang yang kafir?\") Istifham di sini bermakna nafi.",[["فَتَوَلَّىٰ","So he turned away"],["عَنْهُمْ","from them"],["وَقَالَ","and said"],["يَـٰقَوْمِ","O my people"],["لَقَدْ","Verily"],["أَبْلَغْتُكُمْ","I (have) conveyed to you"],["رِسَـٰلَـٰتِ","(the) Messages"],["رَبِّى","(of) my Lord"],["وَنَصَحْتُ","and advised"],["لَكُمْ ۖ","[to] you"],["فَكَيْفَ","So how could"],["ءَاسَىٰ","I grieve"],["عَلَىٰ","for"],["قَوْمٍۢ","a people"],["كَـٰفِرِينَ","(who are) disbelievers"]]],"1048":["(Kami tidaklah mengutus seseorang nabi pun kepada sesuatu negeri) kemudian penduduknya mendustakannya (melainkan Kami timpakan) Kami siksa (kepada penduduknya kesempitan) yakni kemiskinan yang sangat (dan penderitaan) berupa penyakit (supaya mereka tunduk dengan merendahkan diri) mereka mau merendahkan dirinya sehingga mereka mau beriman.",[["وَمَآ","And not"],["أَرْسَلْنَا","We sent"],["فِى","in"],["قَرْيَةٍۢ","a city"],["مِّن","any"],["نَّبِىٍّ","Prophet"],["إِلَّآ","except"],["أَخَذْنَآ","We seized"],["أَهْلَهَا","its people"],["بِٱلْبَأْسَآءِ","with adversity"],["وَٱلضَّرَّآءِ","and hardship"],["لَعَلَّهُمْ","so that they may"],["يَضَّرَّعُونَ","(become) humble"]]],"1049":["(Kemudian Kami ganti) Kami berikan kepada mereka (kesusahan itu) yakni azab itu (dengan kesenangan) kecukupan dan kesehatan (hingga mereka bertambah banyak) makin banyak keturunan dan hartanya (dan mereka berkata,) sebagai ungkapan ingkar terhadap karunia Allah (\"Sesungguhnya nenek moyang kami pun telah merasai penderitaan dan kesenangan\") seperti apa yang sedang kami alami, memang demikianlah hukum alam itu, jadi bukanlah merupakan siksaan dari Allah, maka dari itu tetaplah kamu dengan apa yang sekarang kamu pegang. Allah berfirman, (maka Kami timpakan kepada mereka) siksaan (dengan sekonyong-konyong) secara tiba-tiba (sedangkan mereka tidak menyadarinya) sebelum saat azab itu datang.",[["ثُمَّ","Then"],["بَدَّلْنَا","We changed"],["مَكَانَ","(in) place"],["ٱلسَّيِّئَةِ","(of) the bad"],["ٱلْحَسَنَةَ","the good"],["حَتَّىٰ","until"],["عَفَوا۟","they increased"],["وَّقَالُوا۟","and said"],["قَدْ","Verily"],["مَسَّ","(had) touched"],["ءَابَآءَنَا","our forefathers"],["ٱلضَّرَّآءُ","the adversity"],["وَٱلسَّرَّآءُ","and the ease"],["فَأَخَذْنَـٰهُم","So We seized them"],["بَغْتَةًۭ","suddenly"],["وَهُمْ","while they"],["لَا","(did) not"],["يَشْعُرُونَ","perceive"]]],"1050":["(Dan jika sekiranya penduduk negeri-negeri) yang mendustakan (beriman) terhadap Allah dan rasul-rasul mereka (dan bertakwa) tidak kafir dan maksiat (pastilah Kami akan melimpahkan) dengan dibaca takhfif dan tasydid (kepada mereka berkah dari langit) dengan melalui hujan (dan bumi) dengan melalui tetumbuhan (tetapi mereka mendustakan) rasul-rasul (maka Kami siksa mereka) Kami hukum mereka (disebabkan perbuatan mereka sendiri).",[["وَلَوْ","And if"],["أَنَّ","[that]"],["أَهْلَ","people"],["ٱلْقُرَىٰٓ","(of) the cities"],["ءَامَنُوا۟","(had) believed"],["وَٱتَّقَوْا۟","and feared Allah"],["لَفَتَحْنَا","surely We (would have) opened"],["عَلَيْهِم","upon them"],["بَرَكَـٰتٍۢ","blessings"],["مِّنَ","from"],["ٱلسَّمَآءِ","the heaven"],["وَٱلْأَرْضِ","and the earth"],["وَلَـٰكِن","but"],["كَذَّبُوا۟","they denied"],["فَأَخَذْنَـٰهُم","So We seized them"],["بِمَا","for what"],["كَانُوا۟","they used to"],["يَكْسِبُونَ","earn"]]],"1051":["(Maka apakah merasa aman penduduk negeri-negeri itu) yang mendustakan (dari kedatangan siksaan Kami kepada mereka) yaitu azab Kami (di malam hari) tengah malam (di waktu mereka sedang tidur) dalam keadaan lalai dari kedatangan azab itu.",[["أَفَأَمِنَ","Then did feel secure"],["أَهْلُ","(the) people"],["ٱلْقُرَىٰٓ","(of) the cities"],["أَن","that"],["يَأْتِيَهُم","comes to them"],["بَأْسُنَا","Our punishment"],["بَيَـٰتًۭا","(at) night"],["وَهُمْ","while they"],["نَآئِمُونَ","(were) asleep"]]],"1052":["(Atau apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di waktu matahari sepenggalah naik) pada waktu siang hari (ketika mereka sedang bermain).",[["أَوَأَمِنَ","Or felt secure"],["أَهْلُ","(the) people"],["ٱلْقُرَىٰٓ","(of) the cities"],["أَن","that"],["يَأْتِيَهُم","comes to them"],["بَأْسُنَا","Our punishment"],["ضُحًۭى","(in) daylight"],["وَهُمْ","while they"],["يَلْعَبُونَ","(were) playing"]]],"1053":["(Maka apakah mereka merasa aman dari tipu daya Allah.) yakni istidraj Allah terhadap mereka dengan memberi mereka banyak kenikmatan kemudian Ia menghukum mereka dengan sekonyong-konyong (Tiada yang merasa aman dari tipu daya Allah kecuali hanya orang-orang yang merugi).",[["أَفَأَمِنُوا۟","Then did they feel secure"],["مَكْرَ","(from the) plan"],["ٱللَّهِ ۚ","(of) Allah"],["فَلَا","But not"],["يَأْمَنُ","feel secure"],["مَكْرَ","(from the) plan"],["ٱللَّهِ","(of) Allah"],["إِلَّا","except"],["ٱلْقَوْمُ","the people"],["ٱلْخَـٰسِرُونَ","(who are) the losers"]]],"1054":["(Dan apakah belum jelas) artinya belum terang (bagi orang-orang yang mempusakai bumi ini) sebagai tempat tinggalnya (sesudah) binasanya (penduduknya bahwa) menjadi fa'il berasal dari anna yang ditakhfifkan sedangkan isimnya dibuang, artinya bahwasanya (kalau Kami menghendaki tentu Kami timpakan kepada mereka siksaan) yakni azab (karena dosa-dosanya) sebagaimana telah Kami timpakan siksaan kepada orang-orang sebelum mereka. Kesemua hamzah di empat tempat tersebut semuanya bermakna lit-taubikh/mencela; dan huruf fa dan wawu yang memasuki pada kedua di antaranya untuk tujuan athaf. Menurut suatu qiraat dibaca dengan wawu yang disukunkan pada tempat yang pertama karena diathafkan kepada huruf aw. (Dan) Kami (kunci) Kami lak (hati mereka sehingga mereka tidak dapat mendengar) nasihat dengan pendengaran yang sehat.",[["أَوَلَمْ","Would it not"],["يَهْدِ","guide"],["لِلَّذِينَ","[for] those who"],["يَرِثُونَ","inherit"],["ٱلْأَرْضَ","the land"],["مِنۢ","from"],["بَعْدِ","after"],["أَهْلِهَآ","its people"],["أَن","that"],["لَّوْ","if"],["نَشَآءُ","We willed"],["أَصَبْنَـٰهُم","We (could) afflict them"],["بِذُنُوبِهِمْ ۚ","for their sins"],["وَنَطْبَعُ","and We put a seal"],["عَلَىٰ","over"],["قُلُوبِهِمْ","their hearts"],["فَهُمْ","so they"],["لَا","(do) not"],["يَسْمَعُونَ","hear"]]],"1055":["(Negeri-negeri itu) yang telah disebutkan tadi (Kami ceritakan kepadamu) hai Muhammad (tentang sebagian dari berita-beritanya) cerita-cerita penduduknya (Dan sungguh telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti) yaitu mukjizat-mukjizat yang selalu unggul lagi jelas (maka mereka juga tidak beriman) tatkala rasul-rasul itu datang (kepada apa yang dahulu mereka telah mendustakannya) yang telah mereka ingkari (sebelum itu) sebelum para rasul itu datang, bahkan mereka tetap terus melakukan kekafirannya. (Demikianlah) seperti penguncian itu (Allah mengunci mati hati orang-orang kafir).",[["تِلْكَ","These"],["ٱلْقُرَىٰ","(were) the cities "],["نَقُصُّ","We relate"],["عَلَيْكَ","to you"],["مِنْ","of"],["أَنۢبَآئِهَا ۚ","their news"],["وَلَقَدْ","And certainly"],["جَآءَتْهُمْ","came to them"],["رُسُلُهُم","their Messengers"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["فَمَا","but not"],["كَانُوا۟","they were"],["لِيُؤْمِنُوا۟","to believe"],["بِمَا","in what"],["كَذَّبُوا۟","they (had) denied"],["مِن","from"],["قَبْلُ ۚ","before"],["كَذَٰلِكَ","Thus"],["يَطْبَعُ","(has been) put a seal"],["ٱللَّهُ","(by) Allah"],["عَلَىٰ","on"],["قُلُوبِ","(the) hearts"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"]]],"1056":["(Dan Kami tidak mendapati kebanyakan mereka) maksudnya kebanyakan umat manusia itu (memenuhi janji) menunaikan janji mereka tatkala tiba saat pemenuhannya (Sesungguhnya) ditakhfifkan dari anna (Kami mendapati kebanyakan mereka orang-orang yang fasik).",[["وَمَا","And not"],["وَجَدْنَا","We found"],["لِأَكْثَرِهِم","for most of them"],["مِّنْ","any"],["عَهْدٍۢ ۖ","covenant"],["وَإِن","But"],["وَجَدْنَآ","We found"],["أَكْثَرَهُمْ","most of them"],["لَفَـٰسِقِينَ","certainly, defiantly disobedient"]]],"1057":["(Kemudian Kami utus sesudah rasul-rasul itu) sesudah diutusnya rasul-rasul tersebut (Musa dengan membawa ayat-ayat Kami) yang banyaknya sembilan (kepada Firaun dan pemuka-pemuka kaumnya) golongannya (lalu mereka mengingkari) mengkafiri (ayat-ayat itu. Maka perhatikanlah bagaimana akibat orang-orang yang membuat kerusakan) artinya mereka binasa akibat kekafirannya itu.",[["ثُمَّ","Then"],["بَعَثْنَا","We sent"],["مِنۢ","from"],["بَعْدِهِم","after them"],["مُّوسَىٰ","Musa"],["بِـَٔايَـٰتِنَآ","with Our Signs"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","and his chiefs"],["فَظَلَمُوا۟","But they were unjust"],["بِهَا ۖ","to them"],["فَٱنظُرْ","So see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُفْسِدِينَ","(of) the corrupters"]]],"1058":["(Dan Musa berkata, \"Hai Firaun, sesungguhnya aku ini adalah seorang utusan Tuhan semesta alam\") kepadamu, akan tetapi Firaun mendustakannya dan Musa berkata,",[["وَقَالَ","And said"],["مُوسَىٰ","Musa"],["يَـٰفِرْعَوْنُ","O Firaun"],["إِنِّى","Indeed, I am"],["رَسُولٌۭ","a Messenger"],["مِّن","from"],["رَّبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1059":["(\"Aku lebih berhak) lebih pantas (untuk) agar (tidak mengatakan sesuatu terhadap Allah kecuali yang hak) menurut suatu qiraat dibaca tasydid ya-nya; haqiiqun adalah mubtada sedangkan khabarnya adalah an dan kalimat sesudahnya (Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata dari Tuhanmu, maka lepaskanlah pergi bersamaku) menuju ke negeri Syam (Bani Israel.\") kaum Bani Israel itu selalu ditindas oleh Firaun.",[["حَقِيقٌ","Obligated"],["عَلَىٰٓ","on"],["أَن","that"],["لَّآ","not"],["أَقُولَ","I say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["إِلَّا","except"],["ٱلْحَقَّ ۚ","the truth"],["قَدْ","Verily"],["جِئْتُكُم","I (have) come to you"],["بِبَيِّنَةٍۢ","with a clear Sign"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["فَأَرْسِلْ","so send"],["مَعِىَ","with me"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"]]],"1060":["(Berkatalah) Firaun kepadanya, (\"Jika kamu benar membawa sesuatu ayat) bukti yang memperkuat pengakuanmu (maka datangkanlah bukti itu jika betul kamu termasuk orang-orang yang benar.\") membawa bukti itu.",[["قَالَ","He said"],["إِن","If"],["كُنتَ","you have"],["جِئْتَ","come"],["بِـَٔايَةٍۢ","with a Sign"],["فَأْتِ","then bring"],["بِهَآ","it"],["إِن","if"],["كُنتَ","you are"],["مِنَ","of"],["ٱلصَّـٰدِقِينَ","the truthful"]]],"1061":["(Maka Musa menjatuhkan tongkatnya, lalu seketika itu juga tongkat itu menjadi ular yang sebenarnya) yakni ular yang sangat besar bentuknya.",[["فَأَلْقَىٰ","So he threw"],["عَصَاهُ","his staff"],["فَإِذَا","and suddenly"],["هِىَ","it"],["ثُعْبَانٌۭ","(was) a serpent"],["مُّبِينٌۭ","manifest"]]],"1062":["(Dan ia mengeluarkan tangannya) mengeluarkannya dari dalam sakunya (maka ketika itu juga tangan itu menjadi putih bercahaya menyilaukan (bagi orang-orang yang melihatnya) berbeda warnanya dengan keadaan kulit tangan yang sebenarnya.",[["وَنَزَعَ","And he drew out"],["يَدَهُۥ","his hand"],["فَإِذَا","and suddenly"],["هِىَ","it"],["بَيْضَآءُ","(was) white"],["لِلنَّـٰظِرِينَ","for the observers"]]],"1063":["(Pemuka-pemuka kaum Firaun berkata, \"Sesungguhnya Musa ini adalah ahli sihir yang pandai) yang ulung di dalam ilmu sihir, dan di dalam surah Asy-Syu`ara disebutkan bahwa perkataan ini adalah perkataan Firaun sendiri. Seolah-olah para pemuka kaum Firaun itu mengatakan perkataan tersebut bersama Firaun sendiri, setelah mereka dan dia bermusyawarah tentang hal itu.",[["قَالَ","Said"],["ٱلْمَلَأُ","the chiefs"],["مِن","of"],["قَوْمِ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَسَـٰحِرٌ","(is) surely a magician "],["عَلِيمٌۭ","learned"]]],"1064":["(Yang bermaksud hendak mengeluarkan kamu dari negerimu.\" Firaun berkata, \"Maka apakah yang kamu anjurkan?\")",[["يُرِيدُ","He wants"],["أَن","to"],["يُخْرِجَكُم","drive you out"],["مِّنْ","from"],["أَرْضِكُمْ ۖ","your land"],["فَمَاذَا","so what"],["تَأْمُرُونَ","(do) you instruct"]]],"1065":["(Pemuka-pemuka itu menjawab, \"Beri tangguhlah dia dan saudaranya) tangguhkanlah perkara keduanya (serta kirimlah ke kota-kota beberapa orang yang akan mengumpulkan ahli-ahli sihir) yang menghimpun para ahli sihir.",[["قَالُوٓا۟","They said"],["أَرْجِهْ","Postpone him"],["وَأَخَاهُ","and his brother"],["وَأَرْسِلْ","and send"],["فِى","in"],["ٱلْمَدَآئِنِ","the cities"],["حَـٰشِرِينَ","gatherers"]]],"1066":["(Supaya mereka membawa kepadamu semua ahli sihir) menurut suatu qiraat dibaca sahhaar (yang pandai.\") maksudnya yang dapat melebihi kepandaian ilmu sihir Musa, akhirnya mereka dapat menghimpunnya.",[["يَأْتُوكَ","They (will) bring to you"],["بِكُلِّ","[with] every"],["سَـٰحِرٍ","magician"],["عَلِيمٍۢ","learned"]]],"1067":["(Dan beberapa ahli sihir itu datang kepada Firaun mengatakan, \"Apakah sesungguhnya) menurut qiraat yang lain lafal inna dibaca ainna (kami akan mendapat upah jika kamilah yang menang?\").",[["وَجَآءَ","So came"],["ٱلسَّحَرَةُ","the magicians"],["فِرْعَوْنَ","(to) Firaun"],["قَالُوٓا۟","They said"],["إِنَّ","Indeed"],["لَنَا","for us"],["لَأَجْرًا","surely (will be) a reward"],["إِن","if"],["كُنَّا","we are"],["نَحْنُ","[we]"],["ٱلْغَـٰلِبِينَ","the victors"]]],"1068":["(Firaun menjawab, \"Ya, dan sesungguhnya kamu benar-benar akan termasuk orang-orang yang dekat kepadaku.\")",[["قَالَ","He said"],["نَعَمْ","Yes"],["وَإِنَّكُمْ","and indeed you"],["لَمِنَ","surely (will be) of"],["ٱلْمُقَرَّبِينَ","the ones who are near"]]],"1069":["(Ahli-ahli sihir berkata, \"Hai Musa! Kamukah yang akan melemparkan lebih dahulu) tongkatmu (ataukah kami yang akan melemparkan?\") apa-apa yang ada pada kami.",[["قَالُوا۟","They said"],["يَـٰمُوسَىٰٓ","O Musa"],["إِمَّآ","Whether"],["أَن","[that]"],["تُلْقِىَ","you throw"],["وَإِمَّآ","or Whether"],["أَن","[that]"],["نَّكُونَ","we will be"],["نَحْنُ","[we]"],["ٱلْمُلْقِينَ","the ones to throw"]]],"1070":["(Musa menjawab, \"Lemparkanlah olehmu lebih dahulu) ini adalah suatu perintah yang mempersilakan mereka untuk melemparkan apa yang ada pada mereka, sebagai suatu taktik dari Musa untuk menampakkan yang hak (Maka tatkala mereka melemparkan) tambang-tambang mereka dan tongkat-tongkat mereka (mereka menyulap mata orang) mereka membalik mata para hadirin supaya tidak bisa melihat hal yang sebenarnya (dan menjadikan orang banyak itu takut) artinya mereka membuatnya takut karena mereka menjadikan seolah-olah hal itu adalah ular-ular yang menjalar (serta mereka mendatangkan sihir yang besar, menakjubkan\").",[["قَالَ","He said"],["أَلْقُوا۟ ۖ","Throw"],["فَلَمَّآ","Then when"],["أَلْقَوْا۟","they threw"],["سَحَرُوٓا۟","they bewitched"],["أَعْيُنَ","(the) eyes"],["ٱلنَّاسِ","(of) the people"],["وَٱسْتَرْهَبُوهُمْ","and terrified them"],["وَجَآءُو","and came (up)"],["بِسِحْرٍ","with a magic"],["عَظِيمٍۢ","great"]]],"1071":["(Dan Kami wahyukan kepada Musa, \"Lemparkanlah tongkatmu!\" Maka sekonyong-konyong tongkat itu menelan) dengan membuang salah satu di antara kedua ta yang asal, yakni: tongkat itu mencaplok (apa yang mereka sulapkan) apa yang mereka balikkan pada pandangan mata orang dengan tipu sulap mereka.",[["۞ وَأَوْحَيْنَآ","And We inspired"],["إِلَىٰ","to"],["مُوسَىٰٓ","Musa"],["أَنْ","that"],["أَلْقِ","Throw"],["عَصَاكَ ۖ","your staff"],["فَإِذَا","and suddenly"],["هِىَ","it"],["تَلْقَفُ","swallow(ed)"],["مَا","what"],["يَأْفِكُونَ","they (were) falsifying"]]],"1072":["(Karena itu nyatalah yang benar) yakni telah tetap dan menang yang benar itu (dan batallah yang selalu mereka kerjakan) yaitu perbuatan-perbuatan sihir mereka.",[["فَوَقَعَ","So was established"],["ٱلْحَقُّ","the truth"],["وَبَطَلَ","and became futile"],["مَا","what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"1073":["(Maka mereka kalah) yakni Firaun dan kaumnya (di tempat itu dan jadilah mereka orang-orang yang hina) artinya kini mereka menjadi orang-orang yang kecil lagi hina.",[["فَغُلِبُوا۟","So they were defeated"],["هُنَالِكَ","there"],["وَٱنقَلَبُوا۟","and returned"],["صَـٰغِرِينَ","humiliated"]]],"1074":["(Dan ahli-ahli sihir itu dengan serta-merta meniarapkan diri dengan bersujud).",[["وَأُلْقِىَ","And fell down"],["ٱلسَّحَرَةُ","the magicians"],["سَـٰجِدِينَ","prostrate"]]],"1075":["(Mereka berkata, \"Kami beriman kepada Tuhan semesta alam).",[["قَالُوٓا۟","They said"],["ءَامَنَّا","We believe"],["بِرَبِّ","in (the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1076":["(Yaitu Tuhan Musa dan Harun\") berkat pengetahuan mereka yang menyimpulkan bahwa apa yang telah mereka saksikan itu, yaitu tentang tongkat Musa semata-mata bukanlah perbuatan sihir.",[["رَبِّ","Lord"],["مُوسَىٰ","(of) Musa"],["وَهَـٰرُونَ","and Harun"]]],"1077":["(Firaun berkata, \"Apakah kamu beriman) lafal aamantum dapat dibaca a amantum (kepadanya) kepada Musa (sebelum aku memberi izin) (kepadamu? Sesungguhnya hal ini) apa yang kamu perbuat ini (adalah suatu muslihat yang telah kamu rencanakan di dalam kota ini untuk mengeluarkan penduduknya daripadanya, maka kelak kamu akan mengetahui) apa yang bakal kamu terima balasannya dariku.",[["قَالَ","Said"],["فِرْعَوْنُ","Firaun"],["ءَامَنتُم","You believed"],["بِهِۦ","in him"],["قَبْلَ","before"],["أَنْ","[that]"],["ءَاذَنَ","I give permission"],["لَكُمْ ۖ","to you"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَمَكْرٌۭ","(is) surely a plot"],["مَّكَرْتُمُوهُ","you have plotted it"],["فِى","in"],["ٱلْمَدِينَةِ","the city"],["لِتُخْرِجُوا۟","so that you may drive out"],["مِنْهَآ","from it"],["أَهْلَهَا ۖ","its people"],["فَسَوْفَ","But soon"],["تَعْلَمُونَ","you will know"]]],"1078":["(Demi sesungguhnya aku akan memotong tangan dan kakimu dengan bersilang secara timbal balik) yakni tangan kanan setiap orang akan dipotong berikut kaki sebelah kirinya (kemudian sungguh-sungguh aku akan menyalibmu semuanya.\")",[["لَأُقَطِّعَنَّ","I will surely cut off"],["أَيْدِيَكُمْ","your hands"],["وَأَرْجُلَكُم","and your feet"],["مِّنْ","of"],["خِلَـٰفٍۢ","opposite (sides)"],["ثُمَّ","Then"],["لَأُصَلِّبَنَّكُمْ","I will surely crucify you"],["أَجْمَعِينَ","all"]]],"1079":["(Ahli-ahli sihir itu menjawab, \"Sesungguhnya kepada Tuhan kamilah) sesudah kami mati dengan cara apa pun (kami kembali) dikembalikan kelak di akhirat.",[["قَالُوٓا۟","They said"],["إِنَّآ","Indeed, we"],["إِلَىٰ","to"],["رَبِّنَا","our Lord"],["مُنقَلِبُونَ","(will) return"]]],"1080":["(Dan kamu tidak membalas dendam) maksudnya kamu tidak mengingkari (dengan menyiksa kami melainkan karena kami telah beriman kepada ayat-ayat Tuhan kami ketika ayat-ayat itu datang kepada kami.\" Mereka berdoa, \"Ya Tuhan kami, limpahkanlah kesabaran kepada kami) tatkala dilaksanakannya apa yang diancamkan oleh Firaun agar kami tidak kembali menjadi orang-orang kafir (dan wafatkanlah kami dalam keadaan berserah diri kepada-Mu.\")",[["وَمَا","And not"],["تَنقِمُ","you take revenge"],["مِنَّآ","from us"],["إِلَّآ","except"],["أَنْ","that"],["ءَامَنَّا","we believed"],["بِـَٔايَـٰتِ","in (the) Signs"],["رَبِّنَا","(of) our Lord"],["لَمَّا","when"],["جَآءَتْنَا ۚ","they came to us"],["رَبَّنَآ","Our Lord"],["أَفْرِغْ","Pour"],["عَلَيْنَا","upon us"],["صَبْرًۭا","patience"],["وَتَوَفَّنَا","and cause us to die"],["مُسْلِمِينَ","(as) Muslims"]]],"1081":["(Berkatalah pembesar-pembesar dari kaum Firaun,) kepada Firaun sendiri (\"Apakah kamu membiarkan) meninggalkan (Musa dan kaumnya untuk membuat kerusakan di negeri ini) yaitu dengan menyeru ajakan agar menentangmu (dan meninggalkan kamu serta tuhan-tuhanmu?\") tersebutlah bahwa Firaun itu telah membuat berhala-berhala kecil untuk disembah oleh kaumnya, kemudian Firaun berkata, \"Aku adalah tuhanmu dan tuhan mereka,\" oleh karena itu ia pernah mengatakan, \"Aku adalah tuhanmu yang paling tinggi.\" (Firaun menjawab, \"Akan kita bunuh) dengan mentasydidkan huruf ta-nya (anak-anak lelaki mereka) yang baru dilahirkan (dan kita biarkan hidup) kita biarkan (perempuan-perempuan mereka) sebagaimana yang pernah kita lakukan terhadap mereka sebelumnya (dan sesungguhnya kita berkuasa penuh di atas mereka.\") yakni orang-orang yang berkuasa; akhirnya mereka melakukan hal itu terhadap kaum Musa, sehingga membuat kaum Bani Israel mengadu kepada Musa.",[["وَقَالَ","And said"],["ٱلْمَلَأُ","the chiefs"],["مِن","of"],["قَوْمِ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["أَتَذَرُ","Will you leave"],["مُوسَىٰ","Musa"],["وَقَوْمَهُۥ","and his people"],["لِيُفْسِدُوا۟","so that they cause corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَيَذَرَكَ","and forsake you"],["وَءَالِهَتَكَ ۚ","and your gods"],["قَالَ","He said"],["سَنُقَتِّلُ","We will kill"],["أَبْنَآءَهُمْ","their sons"],["وَنَسْتَحْىِۦ","and we will let live"],["نِسَآءَهُمْ","their women"],["وَإِنَّا","and indeed, we"],["فَوْقَهُمْ","over them"],["قَـٰهِرُونَ","(are) subjugators"]]],"1082":["(Musa berkata kepada kaumnya, \"Mohonlah pertolongan kepada Allah dan bersabarlah) dalam menghadapi penganiayaan mereka (sesungguhnya bumi ini kepunyaan Allah yang dipusakakan-Nya) yang diberi-Nya (kepada siapa yang dikehendaki-Nya dari hamba-hamba-Nya. Dan kesudahan yang baik) yang terpuji (adalah bagi orang-orang yang bertakwa.\") terhadap Allah.",[["قَالَ","Said"],["مُوسَىٰ","Musa"],["لِقَوْمِهِ","to his people"],["ٱسْتَعِينُوا۟","Seek help"],["بِٱللَّهِ","from Allah"],["وَٱصْبِرُوٓا۟ ۖ","and be patient"],["إِنَّ","Indeed"],["ٱلْأَرْضَ","the earth"],["لِلَّهِ","(belongs) to Allah"],["يُورِثُهَا","He causes to inherit it"],["مَن","whom"],["يَشَآءُ","He wills"],["مِنْ","of"],["عِبَادِهِۦ ۖ","His servants"],["وَٱلْعَـٰقِبَةُ","And the end"],["لِلْمُتَّقِينَ","(is) for the righteous"]]],"1083":["(Kaum Musa berkata, \"Kami telah ditindas, oleh Firaun, sebelum kamu datang kepada kami dan sesudah kamu datang.\" Musa menjawab, \"Mudah-mudahan Allah membinasakan musuhmu dan menjadikan kamu khalifah di bumi-Nya, maka Allah akan melihat bagaimana perbuatanmu.\") di dalamnya.",[["قَالُوٓا۟","They said"],["أُوذِينَا","We have been harmed"],["مِن","from"],["قَبْلِ","before"],["أَن","[that]"],["تَأْتِيَنَا","you came to us"],["وَمِنۢ","from"],["بَعْدِ","and after"],["مَا","[what]"],["جِئْتَنَا ۚ","you have come to us"],["قَالَ","He said"],["عَسَىٰ","Perhaps"],["رَبُّكُمْ","your Lord"],["أَن","[that]"],["يُهْلِكَ","will destroy"],["عَدُوَّكُمْ","your enemy"],["وَيَسْتَخْلِفَكُمْ","and make you successors"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَيَنظُرَ","then see"],["كَيْفَ","how"],["تَعْمَلُونَ","you will do"]]],"1084":["(Dan sesungguhnya Kami telah menghukum Firaun dan kaumnya dengan mendatangkan musim kemarau yang panjang) musim paceklik (dan kekurangan buah-buahan supaya mereka mengambil pelajaran) menjadikannya sebagai pelajaran bagi mereka kemudian mereka mau beriman karenanya.",[["وَلَقَدْ","And certainly"],["أَخَذْنَآ","We seized"],["ءَالَ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["بِٱلسِّنِينَ","with years (of famine)"],["وَنَقْصٍۢ","and a deficit"],["مِّنَ","of"],["ٱلثَّمَرَٰتِ","[the] fruits"],["لَعَلَّهُمْ","so that they may"],["يَذَّكَّرُونَ","receive admonition"]]],"1085":["(Kemudian apabila datang kepada mereka kemakmuran) kesuburan tanah dan kecukupan hidup (mereka berkata, \"Ini adalah karena usaha kami\") kami berhak memperolehnya, akan tetapi mereka tidak mau mensyukurinya. (Dan jika mereka ditimpa kesusahan) kekeringan dan musibah/bencana (mereka lemparkan sebab kesialan itu) mereka menganggap kesialan itu (kepada Musa dan orang-orang yang besertanya) dari kalangan orang-orang yang beriman. (Ketahuilah sesungguhnya kesialan mereka itu) rasa sial mereka itu (adalah ketetapan dari Allah) yang sengaja diturunkan kepada mereka (akan tetapi kebanyakan mereka tidak mengetahui) bahwa apa yang menimpa mereka adalah datang dari sisi Allah.",[["فَإِذَا","But when"],["جَآءَتْهُمُ","came to them"],["ٱلْحَسَنَةُ","the good"],["قَالُوا۟","they said"],["لَنَا","For us"],["هَـٰذِهِۦ ۖ","(is) this"],["وَإِن","And if"],["تُصِبْهُمْ","afflicts them"],["سَيِّئَةٌۭ","bad"],["يَطَّيَّرُوا۟","they ascribe evil omens"],["بِمُوسَىٰ","to Musa"],["وَمَن","and who"],["مَّعَهُۥٓ ۗ","(were) with him"],["أَلَآ","Behold"],["إِنَّمَا","Only"],["طَـٰٓئِرُهُمْ","their evil omens"],["عِندَ","(are) with"],["ٱللَّهِ","Allah"],["وَلَـٰكِنَّ","but"],["أَكْثَرَهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1086":["(Dan mereka berkata,) kepada Musa (\"Bagaimana kamu mendatangkan keterangan kepada kami untuk menyihir kami dengan keterangan itu, maka kami sekali-kali tidak akan beriman kepadamu.\") kemudian Musa berdoa agar mereka diberi pelajaran.",[["وَقَالُوا۟","And they said"],["مَهْمَا","Whatever"],["تَأْتِنَا","you bring us"],["بِهِۦ","therewith"],["مِنْ","of"],["ءَايَةٍۢ","(the) sign"],["لِّتَسْحَرَنَا","so that you bewitch us"],["بِهَا","with it"],["فَمَا","then not"],["نَحْنُ","we"],["لَكَ","(will be) in you"],["بِمُؤْمِنِينَ","believers"]]],"1087":["(Maka Kami kirimkan kepada mereka taufan) yaitu air bah yang memasuki rumah-rumah mereka sehingga mencapai setinggi tempat pesanggrahan duduk mereka selama tujuh hari (belalang) kemudian belalang itu memakan persawahan dan buah-buahan milik mereka, demikian pula (kutu) ulat atau sejenis serangga yang memakan apa yang ditinggalkan oleh belalang (katak) kemudian katak itu memenuhi rumah-rumah mereka dan juga makanan-makanan mereka (dan darah) di dalam air milik mereka (sebagai bukti-bukti yang jelas) yang terang (tetapi mereka tetap menyombongkan diri) tidak mau beriman kepada bukti-bukti tersebut (dan mereka adalah kaum yang berdosa).",[["فَأَرْسَلْنَا","So We sent"],["عَلَيْهِمُ","on them"],["ٱلطُّوفَانَ","the flood"],["وَٱلْجَرَادَ","and the locusts"],["وَٱلْقُمَّلَ","and the lice"],["وَٱلضَّفَادِعَ","and the frogs"],["وَٱلدَّمَ","and the blood"],["ءَايَـٰتٍۢ","(as) signs"],["مُّفَصَّلَـٰتٍۢ","manifest"],["فَٱسْتَكْبَرُوا۟","but they showed arrogance"],["وَكَانُوا۟","and they were"],["قَوْمًۭا","a people"],["مُّجْرِمِينَ","criminal"]]],"1088":["(Dan ketika mereka ditimpa azab) yaitu siksaan (mereka pun berkata, \"Hai Musa! Mohonkanlah untuk kami kepada Tuhanmu dengan perantaraan kenabian yang diketahui Allah ada pada sisimu) yang dapat menghilangkan azab dari kami jika kami beriman (Sesungguhnya jika) lam adalah bermakna qasam/sumpah (kamu dapat menghilangkan azab itu dari kami, pasti kami akan beriman kepadamu dan akan kami biarkan Bani Israel pergi bersamamu.\").",[["وَلَمَّا","And when"],["وَقَعَ","fell"],["عَلَيْهِمُ","on them"],["ٱلرِّجْزُ","the punishment"],["قَالُوا۟","they said"],["يَـٰمُوسَى","O Musa"],["ٱدْعُ","Invoke"],["لَنَا","for us"],["رَبَّكَ","your Lord"],["بِمَا","by what"],["عَهِدَ","He has promised"],["عِندَكَ ۖ","to you"],["لَئِن","If"],["كَشَفْتَ","you remove"],["عَنَّا","from us"],["ٱلرِّجْزَ","the punishment"],["لَنُؤْمِنَنَّ","surely, we will believe"],["لَكَ","[for] you"],["وَلَنُرْسِلَنَّ","and surely, we will send"],["مَعَكَ","with you"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"]]],"1089":["(Maka setelah Kami hilangkan) berkat doa Musa (dari mereka azab itu hingga batas waktu yang mereka sampai kepadanya, tiba-tiba mereka mengingkarinya) janjinya dan bersikeras melakukan kekafiran.",[["فَلَمَّا","But when"],["كَشَفْنَا","We removed"],["عَنْهُمُ","from them"],["ٱلرِّجْزَ","the punishment"],["إِلَىٰٓ","till"],["أَجَلٍ","a (fixed) term"],["هُم","(which) they"],["بَـٰلِغُوهُ","were to reach [it]"],["إِذَا","then"],["هُمْ","they"],["يَنكُثُونَ","broke (the word)"]]],"1090":["(Kemudian Kami menghukum mereka, maka Kami tenggelamkan mereka di laut) laut yang airnya asin (disebabkan mereka) dikarenakan mereka (mendustakan ayat-ayat Kami dan mereka adalah orang-orang yang melalaikan ayat-ayat Kami) tetapi mereka tidak mau memikirkannya.",[["فَٱنتَقَمْنَا","So We took retribution"],["مِنْهُمْ","from them"],["فَأَغْرَقْنَـٰهُمْ","and We drowned them"],["فِى","in"],["ٱلْيَمِّ","the sea"],["بِأَنَّهُمْ","because they"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["وَكَانُوا۟","and they were"],["عَنْهَا","to them"],["غَـٰفِلِينَ","heedless"]]],"1091":["(Dan Kami pusakakan kepada kaum yang telah ditindas itu) melalui perbudakan, yaitu mereka adalah kaum Bani Israel (negeri-negeri bagian timur dan bagian baratnya yang telah Kami beri berkah padanya) dengan air dan pohon, ini adalah kata sifat bagi tanah, yang dimaksud adalah tanah Syam (Dan telah sempurnalah perkataan Tuhanmu yang baik) yang dimaksud ialah firman-Nya, \"Dan Kami hendak memberi karunia kepada orang-orang yang tertindas di bumi, Mesir, itu.\" (Q.S. Al-Qashash 5) (untuk Bani Israel disebabkan kesabaran mereka) di dalam menanggung penganiayaan musuh mereka (dan Kami hancurkan) Kami binasakan (apa-apa yang telah dibuat Firaun dan kaumnya) bangunan-bangunannya (dan apa yang telah dibangun mereka) dengan mengkasrahkan ra-nya dan boleh juga didamahkan, yakni bangunan-bangunan yang telah mereka tinggikan.",[["وَأَوْرَثْنَا","And We made inheritors"],["ٱلْقَوْمَ","the people"],["ٱلَّذِينَ","those who"],["كَانُوا۟","were"],["يُسْتَضْعَفُونَ","considered weak "],["مَشَـٰرِقَ","(the) eastern (parts)"],["ٱلْأَرْضِ","(of) the land"],["وَمَغَـٰرِبَهَا","and the western (parts) of it"],["ٱلَّتِى","which"],["بَـٰرَكْنَا","We blessed"],["فِيهَا ۖ","[in it]"],["وَتَمَّتْ","And was fulfilled"],["كَلِمَتُ","(the) word"],["رَبِّكَ","(of) your Lord "],["ٱلْحُسْنَىٰ","the best"],["عَلَىٰ","for"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["بِمَا","because"],["صَبَرُوا۟ ۖ","they were patient"],["وَدَمَّرْنَا","And We destroyed"],["مَا","what"],["كَانَ","used to"],["يَصْنَعُ","make"],["فِرْعَوْنُ","Firaun"],["وَقَوْمُهُۥ","and his people"],["وَمَا","and what"],["كَانُوا۟","they used to"],["يَعْرِشُونَ","erect"]]],"1092":["(Dan Kami seberangkan) Kami lewatkan (Bani Israel ke seberang lautan itu, maka setelah mereka sampai) mereka lewat (pada suatu kaum yang tetap menyembah) dengan dibaca damah atau kasrah huruf kaf-nya (berhala mereka) mereka masih tetap menyembah berhala-berhala itu (Bani Israel berkata, \"Hai Musa! Buatlah untuk kami sebuah tuhan) berhala yang akan kami sembah (sebagaimana mereka mempunyai beberapa tuhan, berhala.\" Musa menjawab, \"Sesungguhnya kamu ini adalah kaum yang bodoh.\") karena kamu membalas karunia Allah atas kamu dengan apa yang tadi kamu katakan.",[["وَجَـٰوَزْنَا","And We led across"],["بِبَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["ٱلْبَحْرَ","the sea"],["فَأَتَوْا۟","Then they came"],["عَلَىٰ","upon"],["قَوْمٍۢ","a people"],["يَعْكُفُونَ","devoted"],["عَلَىٰٓ","to"],["أَصْنَامٍۢ","idols"],["لَّهُمْ ۚ","of theirs"],["قَالُوا۟","They said"],["يَـٰمُوسَى","O Musa"],["ٱجْعَل","Make"],["لَّنَآ","for us"],["إِلَـٰهًۭا","a god"],["كَمَا","like what"],["لَهُمْ","they have"],["ءَالِهَةٌۭ ۚ","gods"],["قَالَ","He said"],["إِنَّكُمْ","Indeed, you"],["قَوْمٌۭ","(are) a people"],["تَجْهَلُونَ","ignorant"]]],"1093":["(Sesungguhnya mereka itu akan dihancurkan) dibinasakan (kepercayaan yang dianutnya dan akan batal apa yang selalu mereka kerjakan).",[["إِنَّ","Indeed"],["هَـٰٓؤُلَآءِ","these"],["مُتَبَّرٌۭ","destroyed"],["مَّا","(is) what"],["هُمْ","they"],["فِيهِ","(are) in it"],["وَبَـٰطِلٌۭ","and vain"],["مَّا","(is) what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"1094":["(Musa menjawab, \"Patutkah aku mencari Tuhan untuk kamu yang selain daripada Allah?\") yakni sesembahan; pada asalnya lafal abghiikum itu ialah abghii lakum (padahal Dialah yang telah melebihkan kamu atas segala umat) di zaman kamu sesuai dengan apa yang dituturkan dalam firman-Nya berikut ini.",[["قَالَ","He said"],["أَغَيْرَ","Should other than"],["ٱللَّهِ","Allah"],["أَبْغِيكُمْ","I seek for you"],["إِلَـٰهًۭا","a god"],["وَهُوَ","while He"],["فَضَّلَكُمْ","has preferred you"],["عَلَى","over"],["ٱلْعَـٰلَمِينَ","the worlds"]]],"1095":["(Dan) ingatlah kamu (ketika Kami menyelamatkan kamu) dan menurut suatu qiraat dibaca anjaakum (dari Firaun dan kaumnya yang mengazab kamu) mereka menyiksa dan menganiaya kamu (dengan azab yang sangat jahat) yakni siksaan/azab yang paling keras, yaitu dalam bentuk (yaitu mereka membunuh anak-anak lelakimu dan membiarkan hidup) tidak membunuh (wanita-wanitamu. Dan pada yang demikian itu) penyelamatan dan siksaan (cobaan) pemberian nikmat dan ujian (dari Tuhanmu, yaitu cobaan yang besar) maka apakah kamu tidak mau mengambil pelajaran darinya sehingga kamu berhenti dari apa yang kamu katakan itu.",[["وَإِذْ","And when"],["أَنجَيْنَـٰكُم","We saved you"],["مِّنْ","from"],["ءَالِ","(the) people"],["فِرْعَوْنَ","(of) Firaun"],["يَسُومُونَكُمْ","who were afflicting you"],["سُوٓءَ","(with) worst"],["ٱلْعَذَابِ ۖ","(of) torment"],["يُقَتِّلُونَ","they were killing"],["أَبْنَآءَكُمْ","your sons"],["وَيَسْتَحْيُونَ","and letting live"],["نِسَآءَكُمْ ۚ","your women"],["وَفِى","And in"],["ذَٰلِكُم","that"],["بَلَآءٌۭ","(was) a trial"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["عَظِيمٌۭ","great"]]],"1096":["(Dan telah Kami janjikan) dengan memakai alif dan tidak memakainya (kepada Musa sesudah berlalu waktu tiga puluh malam) di mana Kami akan berbicara kepadanya seusai masa tersebut agar ia berpuasa terlebih dahulu; masa itu adalah bulan Zulkaidah kemudian Musa berpuasa dan tatkala ia selesai, bau mulutnya masih kurang enak. Akhirnya Musa bersiwak dan Allah swt. memerintahkannya agar melakukan puasa sepuluh hari lagi agar ia dapat berbicara dengan-Nya melalui mulutnya; hal ini telah dijelaskan dalam firman Allah swt. (dan Kami sempurnakan jumlah malam itu dengan sepuluh malam lagi) yakni dari bulan Zulhijah (maka sempurnalah waktu yang telah ditentukan Tuhannya) yaitu waktu yang telah dijanjikan oleh-Nya untuk berbicara dengan-Nya (empat puluh) menjadi hal (malam) menjadi tamyiz. (Dan berkata Musa kepada saudaranya, yaitu Harun) di kala hendak pergi ke bukit untuk bermunajat (\"Gantikanlah aku) maksudnya jadilah engkau sebagai penggantiku (dalam memimpin kaumku dan perbaikilah\") perkara mereka (dan janganlah kamu mengikuti jalan orang-orang yang membuat kerusakan) dengan menyetujui mereka berbuat kemaksiatan.",[["۞ وَوَٰعَدْنَا","And We appointed"],["مُوسَىٰ","(for) Musa"],["ثَلَـٰثِينَ","thirty"],["لَيْلَةًۭ","nights"],["وَأَتْمَمْنَـٰهَا","and We completed them"],["بِعَشْرٍۢ","with ten (more)"],["فَتَمَّ","so was completed"],["مِيقَـٰتُ","(the) set term"],["رَبِّهِۦٓ","(of) his Lord"],["أَرْبَعِينَ","(of) forty"],["لَيْلَةًۭ ۚ","night(s)"],["وَقَالَ","And said"],["مُوسَىٰ","Musa"],["لِأَخِيهِ","to his brother"],["هَـٰرُونَ","Harun"],["ٱخْلُفْنِى","Take my place"],["فِى","in"],["قَوْمِى","my people"],["وَأَصْلِحْ","and do right"],["وَلَا","and (do) not"],["تَتَّبِعْ","follow"],["سَبِيلَ","(the) way"],["ٱلْمُفْسِدِينَ","(of) the corrupters"]]],"1097":["(Dan tatkala Musa datang untuk munajat dengan Kami pada waktu yang telah Kami tentukan) waktu yang telah Kami janjikan kepadanya akan berbicara dengannya pada waktu itu (dan Tuhan telah berfirman kepadanya) tanpa perantara dengan pembicaraan yang dapat Musa dengar dari segala penjuru (berkatalah Musa, \"Ya Tuhanku! Tampakkanlah kepadaku) diri Engkau (agar aku dapat melihat-Mu.\" Tuhan berfirman, \"Kamu sekali-kali tidak sanggup melihat-Ku) artinya kamu tidak akan mampu melihat-Ku; bila hal itu diungkapkan bukan dengan memakai huruf lan, maka pengertiannya berarti melihat Tuhan itu mungkin dapat dilakukan (tetapi lihatlah kepada bukit itu) yang bangunannya lebih kuat daripada dirimu (maka jika ia tetap) tegak seperti sediakala (pada tempatnya, niscaya kamu dapat melihat-Ku\") engkau dapat melihat-Ku dan jika tidak, maka niscaya kamu tidak akan kuat (Tatkala Tuhannya tampak) yakni sebagian dari nur-Nya yang hanya sebesar setengah jari manis, demikianlah menurut penjelasan dari hadis yang telah diriwayatkan oleh Al-Hakim (bagi gunung itu, kejadian itu menjadikan gunung itu hancur luluh) dengan dibaca qashr atau pendek dan panjang, yakni gunung itu menjadi lebur rata dengan tanah (dan Musa jatuh pingsan) tak sadarkan diri karena sangat terkejut melihat apa yang ia saksikan (Maka setelah Musa sadar kembali, dia berkata, \"Maha Suci Engkau) dengan memahasucikan Engkau (aku bertobat kepada Engkau) dari permintaan yang aku tidak diperintahkan mengemukakannya (dan aku orang yang pertama-tama beriman\") pada zamanku ini.",[["وَلَمَّا","And when"],["جَآءَ","came"],["مُوسَىٰ","Musa"],["لِمِيقَـٰتِنَا","to Our appointed place"],["وَكَلَّمَهُۥ","and spoke to him"],["رَبُّهُۥ","his Lord"],["قَالَ","he said"],["رَبِّ","O my Lord"],["أَرِنِىٓ","Show me"],["أَنظُرْ","(that) I may look"],["إِلَيْكَ ۚ","at You"],["قَالَ","He said"],["لَن","Never"],["تَرَىٰنِى","you (can) see Me"],["وَلَـٰكِنِ","but"],["ٱنظُرْ","look"],["إِلَى","at"],["ٱلْجَبَلِ","the mountain"],["فَإِنِ","[then] if"],["ٱسْتَقَرَّ","it remains"],["مَكَانَهُۥ","in its place"],["فَسَوْفَ","then"],["تَرَىٰنِى ۚ","you (will) see Me"],["فَلَمَّا","But when"],["تَجَلَّىٰ","revealed (His) Glory"],["رَبُّهُۥ","his Lord"],["لِلْجَبَلِ","to the mountain"],["جَعَلَهُۥ","He made it"],["دَكًّۭا","crumbled to dust"],["وَخَرَّ","and fell down"],["مُوسَىٰ","Musa"],["صَعِقًۭا ۚ","unconscious"],["فَلَمَّآ","And when"],["أَفَاقَ","he recovered"],["قَالَ","he said"],["سُبْحَـٰنَكَ","Glory be to You"],["تُبْتُ","I turn (in repentance)"],["إِلَيْكَ","to you"],["وَأَنَا۠","and I am"],["أَوَّلُ","(the) first"],["ٱلْمُؤْمِنِينَ","(of) the believers"]]],"1098":["(Allah berfirman,) Maha Tinggi Allah (\"Hai Musa, sesungguhnya Aku memilih melebihkan kamu) yakni Aku memilihmu (dari manusia) yang hidup di masamu (untuk membawa risalah-Ku) dengan memakai jamak dan mufrad/tunggal (dan untuk berbicara langsung dengan-Ku) Aku berbicara kepadamu secara langsung (sebab itu berpegang teguhlah kepada apa yang Aku berikan kepadamu) berupa keutamaan (dan hendaklah kamu termasuk orang-orang yang bersyukur\") atas nikmat-nikmat-Ku.",[["قَالَ","He said"],["يَـٰمُوسَىٰٓ","O Musa"],["إِنِّى","Indeed, I"],["ٱصْطَفَيْتُكَ","have chosen you"],["عَلَى","over"],["ٱلنَّاسِ","the people"],["بِرِسَـٰلَـٰتِى","with My Messages"],["وَبِكَلَـٰمِى","and with My words"],["فَخُذْ","So take"],["مَآ","what"],["ءَاتَيْتُكَ","I have given you"],["وَكُن","and be"],["مِّنَ","among"],["ٱلشَّـٰكِرِينَ","the grateful"]]],"1099":["(Dan telah Kami tuliskan untuk Musa pada lempengan-lempengan) lempengan-lempengan kitab Taurat yang terdiri dari dedaunan surga, atau dari zabarjad atau dari tujuh jenis atau sepuluh jenis zamrud (segala sesuatu) yang diperlukan di dalam menyampaikan agama (sebagai pelajaran dan penjelasan) keterangan (bagi segala sesuatu) menjadi badal dari jar dan majrur sebelumnya. (Maka berpeganglah kepadanya) sebelumnya terdapat kalimat Kami berfirman yang ditakdirkan/yang diperkirakan keberadaannya (dengan teguh) dengan sungguh-sungguh dan dengan segala kemampuan (dan suruhlah kaummu berpegang kepadanya dengan sebaik-baiknya, nanti Aku akan memperlihatkan kepadamu negeri orang-orang yang fasik) yakni Firaun beserta para pengikutnya, yaitu negeri Mesir, supaya kamu mengambil pelajaran darinya.",[["وَكَتَبْنَا","And We ordained (laws)"],["لَهُۥ","for him"],["فِى","in"],["ٱلْأَلْوَاحِ","the tablets "],["مِن","of"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["مَّوْعِظَةًۭ","an instruction"],["وَتَفْصِيلًۭا","and explanation"],["لِّكُلِّ","for every"],["شَىْءٍۢ","thing"],["فَخُذْهَا","So take them"],["بِقُوَّةٍۢ","with firmness"],["وَأْمُرْ","and order"],["قَوْمَكَ","your people"],["يَأْخُذُوا۟","(to) take"],["بِأَحْسَنِهَا ۚ","(the) best of it"],["سَأُو۟رِيكُمْ","I will show you"],["دَارَ","(the) home"],["ٱلْفَـٰسِقِينَ","(of) the defiantly disobedient"]]],"1100":["(Aku akan memalingkan dari ayat-ayat-Ku) dari bukti-bukti yang menunjukkan kekuasaan-Ku, yaitu berupa hasil-hasil ciptaan-Ku dan lain-lainnya (orang-orang yang menyombongkan dirinya di muka bumi tanpa alasan yang benar) yaitu Aku akan menjadikan mereka terhina sehingga tidak lagi mereka berlaku sombong di muka bumi (jika mereka melihat tiap-tiap ayat-Ku, mereka tidak beriman kepadanya. Dan jika mereka melihat jalan) yakni titian (yang membawa kepada petunjuk) hidayah yang datang dari sisi Tuhan (mereka tidak mau menjalankannya sebagai jalan hidup) yang mereka tempuh (tetapi jika mereka melihat jalan kesesatan) jalan yang salah (mereka terus menempuhnya. Yang demikian itu) berpalingnya mereka itu (adalah karena mereka mendustakan ayat-ayat Kami dan mereka selalu lalai daripadanya) contoh mengenai mereka telah disebutkan.",[["سَأَصْرِفُ","I will turn away"],["عَنْ","from"],["ءَايَـٰتِىَ","My Signs"],["ٱلَّذِينَ","those who"],["يَتَكَبَّرُونَ","are arrogant"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بِغَيْرِ","without"],["ٱلْحَقِّ","[the] right"],["وَإِن","and if"],["يَرَوْا۟","they see"],["كُلَّ","every"],["ءَايَةٍۢ","sign"],["لَّا","not"],["يُؤْمِنُوا۟","(will) they believe"],["بِهَا","in it"],["وَإِن","And if"],["يَرَوْا۟","they see"],["سَبِيلَ","(the) way"],["ٱلرُّشْدِ","(of) the righteousness"],["لَا","not"],["يَتَّخِذُوهُ","(will) they take it"],["سَبِيلًۭا","(as) a way"],["وَإِن","but if"],["يَرَوْا۟","they see"],["سَبِيلَ","(the) way"],["ٱلْغَىِّ","(of) [the] error"],["يَتَّخِذُوهُ","they will take it"],["سَبِيلًۭا ۚ","(as) a way"],["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because they"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["وَكَانُوا۟","and they were"],["عَنْهَا","of them"],["غَـٰفِلِينَ","heedless"]]],"1101":["(Dan orang-orang yang mendustakan ayat-ayat Kami dan mendustakan akan menemui akhirat) dimaksud mengenai hari berbangkit dan lain-lainnya (sia-sialah) artinya batillah (perbuatan mereka) yaitu perbuatan-perbuatan yang telah mereka lakukan sewaktu hidup di alam dunia, berupa amal-amal kebaikan seperti silaturahmi dan sedekah, maka mereka tidak lagi mendapat pahalanya karena persyaratannya sudah tidak memenuhi lagi (Tidak) (mereka itu mendapat balasan kecuali) hanya balasan (apa yang telah mereka kerjakan) yakni perbuatan mendustakan ayat-ayat Kami dan perbuatan-perbuatan maksiat.",[["وَٱلَّذِينَ","And those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["وَلِقَآءِ","and (the) meeting"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter "],["حَبِطَتْ","worthless"],["أَعْمَـٰلُهُمْ ۚ","(are) their deeds"],["هَلْ","Will"],["يُجْزَوْنَ","they be recompensed"],["إِلَّا","except"],["مَا","(for) what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"1102":["(Dan kaum Musa, setelah kepergian Musa, mereka membuat) setelah pergi meninggalkan mereka untuk bermunajat (dari perhiasan mereka) yang telah mereka pinjam dari kaumnya Firaun dengan alasan untuk perkawinan (berhala) yang kemudian dipuja-puja oleh mereka (anak lembu) Samirilah yang mencetaknya berdasarkan permintaan mereka (yang bertubuh) sebagai ganti dari daging dan darah (dan bersuara) artinya suara yang dapat didengar; dan dapat bergerak sebab Samiri menaruh debu di mulutnya dari bekas teracak kuda malaikat Jibril, sebagai pengaruhnya berhala itu dapat hidup. Maf'ul dari lafal ittakhadza dibuang yang asalnya ialah lafal ilaahan, yakni sebagai tuhan. (Apakah mereka tidak mengetahui bahwa anak lembu itu tidak dapat berbicara dengan mereka dan tidak dapat pula menunjukkan jalan kepada mereka?) lalu mengapa mereka menganggapnya sebagai tuhan mereka (Mereka menjadikannya) sebagai sesembahan (dan mereka adalah orang-orang yang lalim) disebabkan mengambilnya sebagai sesembahan.",[["وَٱتَّخَذَ","And took"],["قَوْمُ","(the) people"],["مُوسَىٰ","(of) Musa"],["مِنۢ","from"],["بَعْدِهِۦ","after him"],["مِنْ","from"],["حُلِيِّهِمْ","their ornaments"],["عِجْلًۭا","a calf "],["جَسَدًۭا","an image"],["لَّهُۥ","[for] it"],["خُوَارٌ ۚ","(had) a lowing sound"],["أَلَمْ","Did not"],["يَرَوْا۟","they see"],["أَنَّهُۥ","that it"],["لَا","(could) not"],["يُكَلِّمُهُمْ","speak to them"],["وَلَا","and not"],["يَهْدِيهِمْ","guide them"],["سَبِيلًا ۘ","(to) a way"],["ٱتَّخَذُوهُ","They took it (for worship)"],["وَكَانُوا۟","and they were"],["ظَـٰلِمِينَ","wrongdoers"]]],"1103":["(Dan setelah mereka menyesali perbuatannya) mereka menyesal mengambil sebagai sesembahan mereka (dan mereka melihat) mereka mengetahui (bahwa mereka telah sesat) oleh sebab perbuatan itu; penyesalan itu datang setelah Musa kembali kepada mereka (mereka pun berkata, \"Sungguh jika Tuhan kami tidak memberi rahmat kepada kami dan tidak mengampuni kami) dengan memakai ya dan ta pada kedua fi'ilnya (pastilah kami menjadi orang-orang yang merugi.\").",[["وَلَمَّا","And when"],["سُقِطَ","(it was made to) fall"],["فِىٓ","into"],["أَيْدِيهِمْ","their hands"],["وَرَأَوْا۟","and they saw"],["أَنَّهُمْ","that they"],["قَدْ","(had) indeed"],["ضَلُّوا۟","gone astray"],["قَالُوا۟","they said"],["لَئِن","If"],["لَّمْ","not"],["يَرْحَمْنَا","has Mercy on us"],["رَبُّنَا","Our Lord"],["وَيَغْفِرْ","and forgive"],["لَنَا","[for] us"],["لَنَكُونَنَّ","we will surely be"],["مِنَ","among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"1104":["(Dan tatkala Musa kembali kepada kaumnya dalam keadaan marah) oleh sebab perbuatan mereka (dan sedih hati) yakni amat bersedih hati (berkatalah dia,) kepada mereka (\"Alangkah buruknya perbuatan) teramat jelek perbuatan (yang kamu kerjakan) dalam hal ini (sesudah kepergianku!) dimaksud pekerjaanmu ini di mana kamu berlaku musyrik. (Apakah kamu hendak mendahului janji Tuhanmu?\" Dan Musa pun melemparkan lempengan-lempengan) yaitu lempengan-lempengan Kitab Taurat karena marah kepada kaumnya, sehingga lempengan-lempengan itu pecah (dan ia memegang rambut kepala saudaranya) dengan tangan kanannya dan jenggotnya dengan tangan kirinya (sambil menariknya ke arahnya) saking marahnya (Harun berkata,) \"Hai (anak ibuku!) dengan mim dikasrahkan dan difathahkan, yang dimaksud adalah ummi, penyebutan dengan kata-kata ini untuk lebih menimbulkan rasa sayang ke dalam hati Musa (Sesungguhnya kaum ini telah menganggapku lemah dan hampir-hampir mereka) hampir saja (membunuhku, sebab itu janganlah kamu menjadikan gembira) membuat girang (musuh-musuh melihatku) karena kamu menghinakan diriku (dan janganlah kamu masukkan aku ke dalam golongan orang-orang yang lalim.\") sebagaimana engkau memperlakukan orang yang benar-benar menyembah anak sapi.",[["وَلَمَّا","And when"],["رَجَعَ","returned"],["مُوسَىٰٓ","Musa"],["إِلَىٰ","to"],["قَوْمِهِۦ","his people "],["غَضْبَـٰنَ","angry"],["أَسِفًۭا","and grieved"],["قَالَ","he said"],["بِئْسَمَا","Evil is what"],["خَلَفْتُمُونِى","you have done in my place"],["مِنۢ","from"],["بَعْدِىٓ ۖ","after me"],["أَعَجِلْتُمْ","Were you impatient"],["أَمْرَ","(over the) matter"],["رَبِّكُمْ ۖ","(of) your Lord"],["وَأَلْقَى","And he cast down"],["ٱلْأَلْوَاحَ","the tablets"],["وَأَخَذَ","and seized"],["بِرَأْسِ","by head"],["أَخِيهِ","his brother"],["يَجُرُّهُۥٓ","dragging him"],["إِلَيْهِ ۚ","to himself"],["قَالَ","He said"],["ٱبْنَ","O son"],["أُمَّ","(of) my mother"],["إِنَّ","Indeed"],["ٱلْقَوْمَ","the people"],["ٱسْتَضْعَفُونِى","considered me weak"],["وَكَادُوا۟","and were about to"],["يَقْتُلُونَنِى","kill me"],["فَلَا","So (let) not"],["تُشْمِتْ","rejoice"],["بِىَ","over me"],["ٱلْأَعْدَآءَ","the enemies"],["وَلَا","and (do) not"],["تَجْعَلْنِى","place me"],["مَعَ","with"],["ٱلْقَوْمِ","the people"],["ٱلظَّـٰلِمِينَ","(who are) wrongdoing"]]],"1105":["(Musa berdoa, \"Ya Tuhanku! Ampunilah aku) atas apa yang telah kuperbuat terhadap saudaraku (dan saudaraku) Musa menyertakan saudaranya dalam doa demi untuk membuatnya rela atas apa yang telah ia lakukan kepadanya dan sekaligus untuk menolak agar musuh jangan girang melihat sikapnya terhadap saudaranya itu (dan masukkanlah kami ke dalam rahmat Engkau, dan Engkau adalah Maha Penyayang di antara para penyayang.\") Allah berfirman,",[["قَالَ","He said"],["رَبِّ","O my Lord"],["ٱغْفِرْ","Forgive"],["لِى","me"],["وَلِأَخِى","and my brother"],["وَأَدْخِلْنَا","and admit us"],["فِى","into"],["رَحْمَتِكَ ۖ","Your Mercy"],["وَأَنتَ","for You"],["أَرْحَمُ","(are) the Most Merciful"],["ٱلرَّٰحِمِينَ","(of) the merciful"]]],"1106":["(\"Sesungguhnya orang-orang yang menjadikan anak lembu) sebagai sesembahan (kelak akan menimpa mereka kemurkaan) yakni azab (dari Tuhan mereka dan kehinaan dalam kehidupan di dunia) maka mereka dihukum dengan perintah agar mereka membunuh diri mereka sendiri dan kehinaan akan selalu menimpa mereka sampai hari kiamat nanti. (Demikianlah) seperti apa yang telah Kami balaskan kepada mereka (Kami memberi balasan kepada orang-orang yang membuat-buat kebohongan) terhadap Allah dengan melakukan perbuatan syirik dan lain-lainnya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ٱتَّخَذُوا۟","took"],["ٱلْعِجْلَ","the calf"],["سَيَنَالُهُمْ","will reach them"],["غَضَبٌۭ","wrath"],["مِّن","from"],["رَّبِّهِمْ","their Lord"],["وَذِلَّةٌۭ","and humiliation"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا ۚ","(of) the world"],["وَكَذَٰلِكَ","And thus"],["نَجْزِى","We recompense"],["ٱلْمُفْتَرِينَ","the ones who invent (falsehood)"]]],"1107":["(Dan orang-orang yang mengerjakan kejahatan; kemudian bertobat) kembali tidak melakukannya (sesudah itu dan beriman) terhadap Allah (sesungguhnya Tuhan kamu sesudahnya) sesudah tobat (adalah Maha Pengampun) kepada mereka (lagi Maha Penyayang\").",[["وَٱلَّذِينَ","And those who"],["عَمِلُوا۟","do"],["ٱلسَّيِّـَٔاتِ","the evil deeds"],["ثُمَّ","then"],["تَابُوا۟","repented"],["مِنۢ","from"],["بَعْدِهَا","after that"],["وَءَامَنُوٓا۟","and believed"],["إِنَّ","indeed"],["رَبَّكَ","your Lord"],["مِنۢ","from"],["بَعْدِهَا","after that"],["لَغَفُورٌۭ","(is) surely Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"1108":["(Sesudah mereda) telah tenang (amarah Musa, lalu diambilnya kembali lempengan-lempengan itu) yang telah ia banting itu (dan dalam tulisannya) apa yang tertulis di dalam lempengan kitab Taurat itu (terdapat petunjuk) dari kesesatan (dan rahmat untuk orang-orang yang takut kepada Tuhannya) mereka takut kepada-Nya; huruf lam dimasukkan ke dalam maf'ul mengingat tempatnya yang didahulukan.",[["وَلَمَّا","And when"],["سَكَتَ","was calmed"],["عَن","from"],["مُّوسَى","Musa"],["ٱلْغَضَبُ","the anger"],["أَخَذَ","he took (up)"],["ٱلْأَلْوَاحَ ۖ","the tablets"],["وَفِى","and in"],["نُسْخَتِهَا","their inscription"],["هُدًۭى","(was) guidance"],["وَرَحْمَةٌۭ","and mercy"],["لِّلَّذِينَ","for those who"],["هُمْ","[they]"],["لِرَبِّهِمْ","of their Lord"],["يَرْهَبُونَ","(are) fearful"]]],"1109":["(Dan Musa memilih dari kaumnya) dimaksud sebagian dari kaumnya (sebanyak tujuh puluh orang lelaki) dari kalangan orang-orang yang tidak ikut menyembah anak sapi, ia lakukan hal itu berdasarkan perintah dari Allah swt. (untuk memenuhi waktu yang telah Kami tentukan) waktu yang telah Kami janjikan, agar mereka datang tepat pada waktunya, untuk memohon ampunan dari penyembahan terhadap anak sapi yang telah dilakukan oleh teman-teman mereka. Kemudian Musa keluar bersama mereka. (Maka ketika mereka diguncang gempa bumi) yaitu gempa yang dahsyat. Ibnu Abbas mengatakan, \"Sebab mereka tidak melarang kaumnya tatkala menyembah anak sapi itu,\" selanjutnya Ibnu Abbas mengatakan lagi, \"Mereka adalah selain dari orang-orang yang meminta agar dapat melihat Tuhan yang kemudian ditimpa azab berupa sha`iqah\" (Ia berkata,) yakni Musa (\"Ya Tuhanku! Kalau Engkau kehendaki tentulah Engkau membinasakan sebelum ini) sebelum aku keluar bersama mereka; maksud Musa untuk menentukan nasib kaum Bani Israel sehubungan dengan peristiwa penyembahan anak sapi itu, agar jika mereka terkena azab tidak menuduhku sebagai penyebabnya (dan aku. Apakah Engkau membinasakan kami karena perbuatan orang-orang yang kurang akal di antara kami?) Istifham bermakna isti`thaf, memohon belas kasihan, yakni janganlah Engkau menyiksa kami oleh sebab dosa yang dilakukan oleh selain kami. (Tidak lain) (itu) fitnah yang dilakukan oleh orang-orang yang akalnya kurang (kecuali hanyalah fitnah dari Engkau) dimaksud cobaan dari Engkau (Engkau sesatkan dengan cobaan itu siapa yang Engkau kehendaki) kesesatannya (dan Engkau beri petunjuk kepada siapa yang Engkau kehendaki) kehidayahannya. (Engkaulah yang memimpin kami) yang menguasai perkara-perkara kami (maka ampunilah kami, dan berilah kami rahmat dan Engkaulah Pemberi ampun yang sebaik-baiknya.\")",[["وَٱخْتَارَ","And chose"],["مُوسَىٰ","Musa"],["قَوْمَهُۥ","(from) his people"],["سَبْعِينَ","seventy"],["رَجُلًۭا","men"],["لِّمِيقَـٰتِنَا ۖ","for Our appointment"],["فَلَمَّآ","Then when"],["أَخَذَتْهُمُ","seized them"],["ٱلرَّجْفَةُ","the earthquake"],["قَالَ","he said"],["رَبِّ","O my Lord"],["لَوْ","If"],["شِئْتَ","you (had) willed"],["أَهْلَكْتَهُم","You (could) have destroyed them"],["مِّن","from"],["قَبْلُ","before"],["وَإِيَّـٰىَ ۖ","and me"],["أَتُهْلِكُنَا","Would You destroy us"],["بِمَا","for what"],["فَعَلَ","did"],["ٱلسُّفَهَآءُ","the foolish"],["مِنَّآ ۖ","among us"],["إِنْ","Not"],["هِىَ","it (was)"],["إِلَّا","but"],["فِتْنَتُكَ","Your trial"],["تُضِلُّ","You let go astray"],["بِهَا","by it"],["مَن","whom"],["تَشَآءُ","You will"],["وَتَهْدِى","and You guide"],["مَن","whom"],["تَشَآءُ ۖ","You will"],["أَنتَ","You"],["وَلِيُّنَا","(are) our Protector"],["فَٱغْفِرْ","so forgive"],["لَنَا","us"],["وَٱرْحَمْنَا ۖ","and have mercy upon us"],["وَأَنتَ","and You"],["خَيْرُ","(are) Best"],["ٱلْغَـٰفِرِينَ","(of) Forgivers"]]],"1110":["(Dan tetapkanlah) pastikanlah (untuk kami kebaikan di dunia ini dan di akhirat) kebaikan (sesungguhnya kami kembali pada jalan hidayah) maksudnya kami telah bertobat (kepada-Mu. Allah berfirman,) Maha Tinggi Allah (\"Siksa-Ku akan Kutimpakan kepada siapa yang Aku kehendaki) Aku ingin menyiksanya (dan rahmat-Ku meliputi) menyeluruh (segala sesuatu) yang ada di dunia (Maka akan Aku tetapkan rahmat-Ku) di akhirat kelak (untuk orang-orang yang bertakwa yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami.\")",[["۞ وَٱكْتُبْ","And ordain"],["لَنَا","for us"],["فِى","in"],["هَـٰذِهِ","this"],["ٱلدُّنْيَا","[the] world"],["حَسَنَةًۭ","good"],["وَفِى","and in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["إِنَّا","Indeed, we"],["هُدْنَآ","we have turned"],["إِلَيْكَ ۚ","to You"],["قَالَ","He said"],["عَذَابِىٓ","My punishment "],["أُصِيبُ","I afflict"],["بِهِۦ","with it"],["مَنْ","whom"],["أَشَآءُ ۖ","I will"],["وَرَحْمَتِى","but My Mercy"],["وَسِعَتْ","encompasses"],["كُلَّ","every"],["شَىْءٍۢ ۚ","thing"],["فَسَأَكْتُبُهَا","So I will ordain it"],["لِلَّذِينَ","for those who"],["يَتَّقُونَ","(are) righteous"],["وَيُؤْتُونَ","and give"],["ٱلزَّكَوٰةَ","zakah"],["وَٱلَّذِينَ","and those who"],["هُم","[they]"],["بِـَٔايَـٰتِنَا","in Our Verses"],["يُؤْمِنُونَ","they believe"]]],"1111":["(Yaitu orang-orang yang mengikut rasul, nabi yang ummi) yaitu Nabi Muhammad saw. (yang namanya mereka dapati tertulis di dalam Taurat dan Injil yang ada di sisi mereka) lengkap dengan nama dan ciri-cirinya (yang menyuruh mereka mengerjakan yang makruf dan melarang mereka dari mengerjakan yang mungkar dan menghalalkan bagi mereka segala yang baik) dari apa yang sebelumnya diharamkan oleh syariat mereka (dan mengharamkan bagi mereka segala yang buruk) yaitu bangkai dan lain-lainnya (dan membuang dari mereka beban-beban) maksud tanggungan mereka (dan belenggu-belenggu) hal-hal yang berat (yang ada pada mereka) seperti bertobat dengan jalan membunuh diri dan memotong apa yang terkena oleh najis. (Maka orang-orang yang beriman kepadanya) dari kalangan mereka (memuliakannya) yaitu menghormatinya (menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya) yakni Alquran (mereka itulah orang-orang yang beruntung).",[["ٱلَّذِينَ","Those who"],["يَتَّبِعُونَ","follow"],["ٱلرَّسُولَ","the Messenger"],["ٱلنَّبِىَّ","the Prophet"],["ٱلْأُمِّىَّ","the unlettered"],["ٱلَّذِى","whom"],["يَجِدُونَهُۥ","they find him"],["مَكْتُوبًا","written"],["عِندَهُمْ","with them"],["فِى","in"],["ٱلتَّوْرَىٰةِ","the Taurat"],["وَٱلْإِنجِيلِ","and the Injeel"],["يَأْمُرُهُم","He commands them"],["بِٱلْمَعْرُوفِ","to the right"],["وَيَنْهَىٰهُمْ","and forbids them"],["عَنِ","from"],["ٱلْمُنكَرِ","the wrong"],["وَيُحِلُّ","and he makes lawful"],["لَهُمُ","for them"],["ٱلطَّيِّبَـٰتِ","the pure things"],["وَيُحَرِّمُ","and makes unlawful"],["عَلَيْهِمُ","for them"],["ٱلْخَبَـٰٓئِثَ","the impure things"],["وَيَضَعُ","and he relieves"],["عَنْهُمْ","from them"],["إِصْرَهُمْ","their burden"],["وَٱلْأَغْلَـٰلَ","and the fetters"],["ٱلَّتِى","which"],["كَانَتْ","were"],["عَلَيْهِمْ ۚ","upon them"],["فَٱلَّذِينَ","So those who"],["ءَامَنُوا۟","believe"],["بِهِۦ","in him"],["وَعَزَّرُوهُ","and honor him"],["وَنَصَرُوهُ","and help him"],["وَٱتَّبَعُوا۟","and follow"],["ٱلنُّورَ","the light"],["ٱلَّذِىٓ","which"],["أُنزِلَ","has been sent down"],["مَعَهُۥٓ ۙ","with him "],["أُو۟لَـٰٓئِكَ","Those (are)"],["هُمُ","[they]"],["ٱلْمُفْلِحُونَ","the successful ones"]]],"1112":["(Katakanlah,) pembicaraan ini ditujukan kepada Nabi saw. (\"Hai manusia! Sesungguhnya aku adalah utusan Allah kepadamu semua, yaitu Allah yang mempunyai kerajaan langit dan bumi; tidak ada Tuhan selain Dia; yang menghidupkan dan mematikan, maka berimanlah kamu kepada Allah dan rasul-Nya, nabi yang ummi yang beriman kepada Allah dan kepada kalimat-kalimat-Nya) yakni Alquran (dan ikutilah dia, supaya kamu mendapat petunjuk.\") artinya kamu akan mendapat bimbingan hidayah.",[["قُلْ","Say"],["يَـٰٓأَيُّهَا","O"],["ٱلنَّاسُ","mankind"],["إِنِّى","Indeed I am"],["رَسُولُ","(the) Messenger"],["ٱللَّهِ","(of) Allah"],["إِلَيْكُمْ","to you"],["جَمِيعًا","all"],["ٱلَّذِى","the One"],["لَهُۥ","for Whom"],["مُلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۖ","and the earth"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ","Him"],["يُحْىِۦ","He gives life"],["وَيُمِيتُ ۖ","and causes death"],["فَـَٔامِنُوا۟","So believe"],["بِٱللَّهِ","in Allah"],["وَرَسُولِهِ","and His Messenger"],["ٱلنَّبِىِّ","the Prophet"],["ٱلْأُمِّىِّ","the unlettered"],["ٱلَّذِى","the one who"],["يُؤْمِنُ","believes"],["بِٱللَّهِ","in Allah"],["وَكَلِمَـٰتِهِۦ","and His Words"],["وَٱتَّبِعُوهُ","and follow him"],["لَعَلَّكُمْ","so that you may"],["تَهْتَدُونَ","(be) guided"]]],"1113":["(Dan di antara kaum Musa itu terdapat suatu umat) suatu jemaah (yang memberi petunjuk) kepada manusia (dengan hak dan dengan yang hak itulah mereka menjalankan keadilan) di dalam memberikan keputusan hukum.",[["وَمِن","And among"],["قَوْمِ","(the) people"],["مُوسَىٰٓ","(of) Musa"],["أُمَّةٌۭ","(is) a community"],["يَهْدُونَ","(which) guides"],["بِٱلْحَقِّ","with truth"],["وَبِهِۦ","and by it"],["يَعْدِلُونَ","establishes justice"]]],"1114":["(Dan Kami bagi mereka) Kami pecahkan kaum Bani Israel (menjadi dua belas) sebagai hal (suku-suku) menjadi badal dari yang sebelumnya, yaitu kabilah-kabilah (yang masing-masingnya berjumlah besar) menjadi badal dari yang sebelumnya (dan Kami wahyukan kepada Musa ketika kaumnya meminta air kepadanya,) di tengah padang sahara (\"Pukullah batu itu dengan tongkatmu!\") kemudian Musa memukulkannya (maka memancarlah) maksudnya tersemburlah (daripadanya dua belas mata air) sesuai dengan bilangan kabilah (Sesungguhnya tiap-tiap suku telah mengetahui) setiap suku dari kalangan mereka (tempat minum masing-masing. Dan Kami naungkan awan di atas mereka) di padang pasir tempat mereka berada guna melindungi mereka dari panasnya matahari (dan Kami turunkan kepada mereka manna dan salwa) keduanya adalah taranjabin, makanan manis seperti madu, dan sebangsa burung puyuh dengan ditakhfifkan mimnya dan dibaca pendek. Dan Kami berfirman kepada mereka, (\"Makanlah yang baik-baik dari apa yang telah Kami rezekikan kepadamu.\" Mereka tidak menganiaya Kami, tetapi merekalah yang selalu menganiaya dirinya sendiri).",[["وَقَطَّعْنَـٰهُمُ","And We divided them"],["ٱثْنَتَىْ","(into) two"],["عَشْرَةَ","(and) ten [i.e. twelve]"],["أَسْبَاطًا","tribes"],["أُمَمًۭا ۚ","(as) communities"],["وَأَوْحَيْنَآ","And We inspired"],["إِلَىٰ","to"],["مُوسَىٰٓ","Musa"],["إِذِ","when"],["ٱسْتَسْقَىٰهُ","asked him for water"],["قَوْمُهُۥٓ","his people"],["أَنِ","[that]"],["ٱضْرِب","Strike"],["بِّعَصَاكَ","with your staff"],["ٱلْحَجَرَ ۖ","the stone"],["فَٱنۢبَجَسَتْ","Then gushed forth"],["مِنْهُ","from it"],["ٱثْنَتَا","two"],["عَشْرَةَ","(and) ten [i.e. twelve]"],["عَيْنًۭا ۖ","springs"],["قَدْ","Certainly"],["عَلِمَ","knew"],["كُلُّ","each"],["أُنَاسٍۢ","people"],["مَّشْرَبَهُمْ ۚ","their drinking place"],["وَظَلَّلْنَا","And We shaded"],["عَلَيْهِمُ","[on] them"],["ٱلْغَمَـٰمَ","(with) the clouds"],["وَأَنزَلْنَا","and We sent down"],["عَلَيْهِمُ","upon them"],["ٱلْمَنَّ","the manna"],["وَٱلسَّلْوَىٰ ۖ","and the quails"],["كُلُوا۟","Eat"],["مِن","from"],["طَيِّبَـٰتِ","(the) good things"],["مَا","which"],["رَزَقْنَـٰكُمْ ۚ","We have provided you"],["وَمَا","And not"],["ظَلَمُونَا","they wronged Us"],["وَلَـٰكِن","but"],["كَانُوٓا۟","they were"],["أَنفُسَهُمْ","(to) themselves"],["يَظْلِمُونَ","doing wrong"]]],"1115":["(Dan) Ingatlah (ketika dikatakan kepada mereka, Bani Israel, \"Diamlah di negeri ini saja) yaitu Baitulmakdis (dan makanlah dari hasil buminya di mana saja kamu kehendaki. Dan katakanlah,) perintah Kami ('Bebaskanlah kami dari dosa kami' dan masukilah pintunya) pintu gerbang negeri itu (sambil membungkuk) dengan membungkukkan punggung (niscaya Kami ampuni) dengan memakai nun dan ta, dan bina maf'ul (kesalahan-kesalahanmu.\" Kelak Kami akan tambah pahala kepada orang-orang yang berbuat baik) orang-orang yang taat pahala.",[["وَإِذْ","And when"],["قِيلَ","it was said"],["لَهُمُ","to them"],["ٱسْكُنُوا۟","Live"],["هَـٰذِهِ","(in) this"],["ٱلْقَرْيَةَ","city"],["وَكُلُوا۟","and eat"],["مِنْهَا","from it"],["حَيْثُ","wherever"],["شِئْتُمْ","you wish"],["وَقُولُوا۟","and say"],["حِطَّةٌۭ","Repentance"],["وَٱدْخُلُوا۟","and enter"],["ٱلْبَابَ","the gate"],["سُجَّدًۭا","prostrating"],["نَّغْفِرْ","We will forgive"],["لَكُمْ","for you"],["خَطِيٓـَٔـٰتِكُمْ ۚ","your sins"],["سَنَزِيدُ","We will increase (reward)"],["ٱلْمُحْسِنِينَ","(of) the good-doers"]]],"1116":["(Maka orang-orang yang lalim di antara mereka itu mengganti perkataan itu dengan perkataan yang tidak dikatakan kepada mereka) mereka mengatakan, \"Habbatun fii sya`ratin sebagai ganti dari hiththatun\" dan kemudian mereka memasuki pintu gerbangnya sambil merangkak bukannya membungkukkan badan (maka Kami timpakan kepada mereka azab) yakni siksaan (dari langit disebabkan kelaliman mereka.)",[["فَبَدَّلَ","But changed"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["مِنْهُمْ","among them"],["قَوْلًا","word"],["غَيْرَ","other than"],["ٱلَّذِى","(that) which"],["قِيلَ","was said"],["لَهُمْ","to them"],["فَأَرْسَلْنَا","So We sent"],["عَلَيْهِمْ","upon them"],["رِجْزًۭا","torment"],["مِّنَ","from"],["ٱلسَّمَآءِ","the sky"],["بِمَا","because"],["كَانُوا۟","they were"],["يَظْلِمُونَ","doing wrong"]]],"1117":["(Dan tanyakanlah kepada Bani Israel) hai Muhammad, sebagai celaan (tentang negeri yang terletak di dekat laut) di pinggir laut Qalzum yaitu kota Aylah; yang dipertanyakan ialah tentang apa yang terjadi atas penduduknya (ketika mereka melanggar aturan) saat mereka melakukan pelanggaran (pada hari Sabtu) di mana mereka berburu ikan yang pada hari itu mereka dilarang melakukannya (di waktu) merupakan zharaf dari lafal ya'duuna (datang kepada mereka ikan-ikan pada hari Sabtunya dengan terapung-apung pada pinggirannya) yang tampak di permukaan air (dan di hari-hari yang bukan Sabtu) maksudnya di mana mereka sudah tidak lagi terikat dengan pengagungan hari Sabtu, atau dengan kata lain ialah hari-hari selain hari Sabtu (ikan-ikan itu tidak datang kepada mereka) sebagai ujian dari Allah. (Demikianlah Kami mencoba mereka disebabkan mereka berlaku fasik) dan tatkala mereka hendak berburu ikan para penduduk kota terbagi suaranya menjadi tiga bagian; sebagian berpendapat ikut berburu bersama orang-orang yang berburu, sebagian lainnya mencegah mereka melakukannya dan sebagian lainnya bersikap abstain, tidak ikut dan juga tidak melarang.",[["وَسْـَٔلْهُمْ","And ask them"],["عَنِ","about"],["ٱلْقَرْيَةِ","the town"],["ٱلَّتِى","which"],["كَانَتْ","was"],["حَاضِرَةَ","situated"],["ٱلْبَحْرِ","(by) the sea"],["إِذْ","when"],["يَعْدُونَ","they transgressed"],["فِى","in"],["ٱلسَّبْتِ","the (matter of) Sabbath"],["إِذْ","when"],["تَأْتِيهِمْ","came to them"],["حِيتَانُهُمْ","their fish"],["يَوْمَ","(on the) day"],["سَبْتِهِمْ","(of) their Sabbath"],["شُرَّعًۭا","visibly"],["وَيَوْمَ","and (on the) day"],["لَا","not"],["يَسْبِتُونَ ۙ","they had Sabbath"],["لَا","(they did) not"],["تَأْتِيهِمْ ۚ","come to them"],["كَذَٰلِكَ","Thus"],["نَبْلُوهُم","We test them"],["بِمَا","because"],["كَانُوا۟","they were"],["يَفْسُقُونَ","defiantly disobeying"]]],"1118":["(Dan ketika) diathafkan kepada lafal idz yang sebelumnya (suatu umat di antara mereka berkata,) yaitu kaum yang tidak ikut berburu dan juga tidak melarang orang-orang yang berburu (\"Mengapa kamu menasihati kaum yang Allah akan membinasakan mereka atau mengazab mereka dengan azab yang keras?\" Mereka menjawab,) nasihat kami (\"Agar kami mempunyai alasan) yang bisa dijadikan sebagai pelepas tanggung jawab (kepada Tuhanmu) supaya kami tidak dituduh lalai dalam masalah tidak memberikan larangan kepada mereka (dan supaya mereka bertakwa.\") tidak berani melakukan perburuan lagi.",[["وَإِذْ","And when"],["قَالَتْ","said"],["أُمَّةٌۭ","a community"],["مِّنْهُمْ","among them"],["لِمَ","Why"],["تَعِظُونَ","(do) you preach"],["قَوْمًا ۙ","a people"],["ٱللَّهُ","(whom) Allah"],["مُهْلِكُهُمْ","(is going to) destroy them"],["أَوْ","or"],["مُعَذِّبُهُمْ","punish them"],["عَذَابًۭا","(with) a punishment"],["شَدِيدًۭا ۖ","severe"],["قَالُوا۟","They said"],["مَعْذِرَةً","To be absolved"],["إِلَىٰ","before"],["رَبِّكُمْ","your Lord"],["وَلَعَلَّهُمْ","and that they may"],["يَتَّقُونَ","become righteous"]]],"1119":["(Maka tatkala mereka melupakan) yaitu mereka meninggalkan (apa yang diperingatkan kepada mereka) apa yang dinasihatkan kepada mereka (tentang hal itu) kemudian mereka tidak mau juga menuruti nasihat (Kami selamatkan orang-orang yang melarang dari perbuatan jahat dan Kami timpakan kepada orang-orang yang lalim) yang melakukan pelanggaran (siksaan yang berat) yang keras (disebabkan mereka selalu berbuat fasik.)",[["فَلَمَّا","So when"],["نَسُوا۟","they forgot"],["مَا","what"],["ذُكِّرُوا۟","they had been reminded"],["بِهِۦٓ","with [it]"],["أَنجَيْنَا","We saved"],["ٱلَّذِينَ","those who"],["يَنْهَوْنَ","forbade"],["عَنِ","[from]"],["ٱلسُّوٓءِ","the evil"],["وَأَخَذْنَا","and We seized"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","wronged"],["بِعَذَابٍۭ","with a punishment"],["بَـِٔيسٍۭ","wretched"],["بِمَا","because"],["كَانُوا۟","they were"],["يَفْسُقُونَ","defiantly disobeying"]]],"1120":["(Maka tatkala mereka bersikap sombong) yakni bersikap takabur (terhadap) tidak mau meninggalkan (apa yang dilarang mereka mengerjakannya, Kami katakan kepada mereka, \"Jadilah kamu kera yang hina.\") yang terhina, maka jadilah mereka itu kera yang hina; keterangan ini adalah penjelasan dari apa yang telah lalu. Ibnu Abbas mengatakan, \"Saya tidak mengetahui tentang apa yang terjadi dengan golongan yang bersikap abstain.\" Ikrimah mengatakan, \"Mereka tidak dibinasakan, sebab mereka membenci apa yang telah dilakukan rekan-rekannya dan mereka mengatakan, 'Mengapa kamu menasihati....'.\" Hakim telah meriwayatkan dari Ibnu Abbas bahwa golongan tersebut ikut pula melakukannya dan bahkan takjub dengan sikap mereka yang melakukannya.",[["فَلَمَّا","So when"],["عَتَوْا۟","they exceeded all bounds"],["عَن","about"],["مَّا","what"],["نُهُوا۟","they were forbidden"],["عَنْهُ","from it"],["قُلْنَا","We said"],["لَهُمْ","to them"],["كُونُوا۟","Be"],["قِرَدَةً","apes"],["خَـٰسِـِٔينَ","despised"]]],"1121":["(Dan ketika memberitahukan) mempermaklumkan (Tuhanmu, bahwa sesungguhnya Dia akan mengirim kepada mereka) dimaksud orang-orang Yahudi (sampai hari kiamat orang-orang yang akan menimpakan kepada mereka azab yang seburuk-buruknya) dengan dihinakan dan dibebani pajak/jizyah; kemudian Allah mengutus Nabi Sulaiman kepada mereka, dan sesudah itu Raja Bukhtunasher (Nebukat Nezar) yang membunuh dan menawan mereka serta mewajibkan mereka membayar jizyah. Mereka selalu membayar jizyah kepada orang-orang Majusi sehingga Allah swt. mengutus nabi kita Muhammad saw. yang kemudian mengambil pula jizyah dari mereka. (Sesungguhnya Tuhanmu amat cepat siksa-Nya) (dan sesungguhnya Dia Maha Pengampun) terhadap orang-orang yang taat kepada-Nya (lagi Maha Penyayang) terhadap mereka yang taat.",[["وَإِذْ","And when"],["تَأَذَّنَ","declared"],["رَبُّكَ","your Lord"],["لَيَبْعَثَنَّ","that He would surely send"],["عَلَيْهِمْ","upon them"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["مَن","(those) who"],["يَسُومُهُمْ","would afflict them"],["سُوٓءَ","(with) a grievous"],["ٱلْعَذَابِ ۗ","[the] punishment"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["لَسَرِيعُ","(is) surely swift"],["ٱلْعِقَابِ ۖ","(in) the retribution"],["وَإِنَّهُۥ","but indeed, He"],["لَغَفُورٌۭ","(is) surely Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"1122":["(Dan Kami bagi-bagi mereka) Kami pecah-pecah mereka (di dunia menjadi beberapa golongan) terdiri dari beberapa golongan (di antaranya ada orang-orang yang saleh dan di antaranya) ada orang-orang (yang tidak demikian) yaitu menjadi orang-orang kafir dan orang-orang fasik (Dan Kami coba mereka dengan yang baik-baik) yang nikmat-nikmat (dan yang buruk-buruk) dengan bencana-bencana (agar mereka kembali) kepada kebenaran dan tidak mau berbuat fasik lagi.",[["وَقَطَّعْنَـٰهُمْ","And We divided them"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["أُمَمًۭا ۖ","(as) nations"],["مِّنْهُمُ","Among them"],["ٱلصَّـٰلِحُونَ","(are) the righteous"],["وَمِنْهُمْ","and among them"],["دُونَ","(are) other than"],["ذَٰلِكَ ۖ","that"],["وَبَلَوْنَـٰهُم","And We tested them"],["بِٱلْحَسَنَـٰتِ","with the good"],["وَٱلسَّيِّـَٔاتِ","and the bad"],["لَعَلَّهُمْ","so that they may"],["يَرْجِعُونَ","return"]]],"1123":["(Maka datanglah sesudah mereka generasi yang jahat yang mewarisi Alkitab) yakni kitab Taurat dari para pendahulu mereka (yang mengambil harta benda dunia yang rendah ini) sesuatu yang tidak ada harganya, yaitu duniawi baik yang halal maupun yang haram (dan berkata, \"Kami akan diberi ampun.\") atas apa yang telah kami lakukan. (Dan kelak jika datang kepada mereka harta benda dunia sebanyak itu pula niscaya mereka akan mengambilnya juga) jumlah kalimat ini menjadi hal; artinya mereka masih juga mengharapkan ampunan sedangkan mereka masih tetap kembali melakukannya padahal di dalam kitab Taurat tidak ada janji ampunan jika disertai dengan menetapi perbuatan dosa (bukankah sudah diambil) Istifham atau kata tanya bermakna menetapkan (perjanjian kitab Taurat dari mereka) Idhafah di sini bermakna fii (yaitu bahwa mereka tidak akan mengatakan terhadap Allah kecuali yang benar, padahal mereka telah mempelajari) diathafkan kepada lafal yu`khadzu, yakni mereka telah membaca (apa yang tersebut di dalamnya?) maka mengapa mereka mendustakan tentang masalah ampunan itu, sedangkan mereka masih terus menepati perbuatan dosanya. (Dan kampung akhirat itu lebih baik bagi mereka yang bertakwa) yang takut terhadap perbuatan haram. (Maka apakah mereka tidak mengerti) dengan memakai ya dan ta, sesungguhnya pahala akhirat itu lebih baik yang seharusnya mereka lebih memilihnya daripada perkara duniawi.",[["فَخَلَفَ","Then succeeded"],["مِنۢ","from"],["بَعْدِهِمْ","after them"],["خَلْفٌۭ","successors"],["وَرِثُوا۟","(who) inherited"],["ٱلْكِتَـٰبَ","the Book"],["يَأْخُذُونَ","taking"],["عَرَضَ","goods"],["هَـٰذَا","(of) this"],["ٱلْأَدْنَىٰ","the lower (life)"],["وَيَقُولُونَ","and they say"],["سَيُغْفَرُ","It will be forgiven"],["لَنَا","for us"],["وَإِن","And if"],["يَأْتِهِمْ","comes to them"],["عَرَضٌۭ","goods"],["مِّثْلُهُۥ","similar to it"],["يَأْخُذُوهُ ۚ","they will take it"],["أَلَمْ","Was not"],["يُؤْخَذْ","taken"],["عَلَيْهِم","on them"],["مِّيثَـٰقُ","Covenant"],["ٱلْكِتَـٰبِ","(of) the Book"],["أَن","that"],["لَّا","not"],["يَقُولُوا۟","they will say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["إِلَّا","except"],["ٱلْحَقَّ","the truth"],["وَدَرَسُوا۟","while they studied"],["مَا","what"],["فِيهِ ۗ","(is) in it"],["وَٱلدَّارُ","And the home"],["ٱلْـَٔاخِرَةُ","(of) the Hereafter"],["خَيْرٌۭ","(is) better"],["لِّلَّذِينَ","for those who"],["يَتَّقُونَ ۗ","fear Allah"],["أَفَلَا","So will not"],["تَعْقِلُونَ","you use intellect"]]],"1124":["(Dan orang-orang yang berpegang teguh) dengan memakai tasydid dan tidak/takhfif (dengan Alkitab Taurat) yaitu sebagian di antara mereka (serta mendirikan salat) seperti Abdullah bin Salam dan teman-temannya. (Sesungguhnya Kami tidak menyia-nyiakan pahala orang-orang yang mengadakan perbaikan) Jumlah kalimat ini menjadi khabar dari lafal lilladziina; dan di dalamnya terkandung meletakkan isim zhahir pada tempat isim dhamir; yakni ajrahum/pahala mereka.",[["وَٱلَّذِينَ","And those who"],["يُمَسِّكُونَ","hold fast"],["بِٱلْكِتَـٰبِ","to the Book"],["وَأَقَامُوا۟","and establish"],["ٱلصَّلَوٰةَ","the prayer"],["إِنَّا","indeed, We"],["لَا","(will) not"],["نُضِيعُ","[We] let go waste"],["أَجْرَ","(the) reward"],["ٱلْمُصْلِحِينَ","(of) the reformers"]]],"1125":["(Dan) ingatlah (ketika Kami mengangkat bukit) yaitu Kami mencabutnya dari dasarnya (ke atas mereka seakan-akan bukit itu naungan awan dan mereka menduga) dan merasa yakin (bahwa bukit itu akan jatuh menimpa mereka) akan jatuh kepada mereka sesuai dengan janji Allah kepada mereka, bahwa hal itu akan menimpa mereka jika mereka tidak mau menerima hukum-hukum syariat kitab Taurat. Mereka menolaknya mengingat hal itu teramat berat pada permulaannya tetapi kemudian mereka mau menerimanya. Kami berfirman kepada mereka, (\"Peganglah dengan teguh apa yang telah Kami berikan kepadamu) dengan sungguh-sungguh dan dengan segala kemampuan (serta ingatlah selalu apa yang tersebut di dalamnya) dengan mengamalkannya (supaya kamu menjadi orang-orang yang bertakwa.\").",[["۞ وَإِذْ","And when"],["نَتَقْنَا","We raised"],["ٱلْجَبَلَ","the mountain"],["فَوْقَهُمْ","above them"],["كَأَنَّهُۥ","as if it was"],["ظُلَّةٌۭ","a canopy"],["وَظَنُّوٓا۟","and they thought"],["أَنَّهُۥ","that it"],["وَاقِعٌۢ","(would) fall"],["بِهِمْ","upon them"],["خُذُوا۟","(We said), \"Take"],["مَآ","what"],["ءَاتَيْنَـٰكُم","We have given you"],["بِقُوَّةٍۢ","with strength"],["وَٱذْكُرُوا۟","and remember"],["مَا","what"],["فِيهِ","(is) in it"],["لَعَلَّكُمْ","so that you may"],["تَتَّقُونَ","fear Allah"]]],"1126":["(Dan) ingatlah (ketika) sewaktu (Tuhanmu mengeluarkan keturunan anak-anak Adam dari sulbi mereka) menjadi badal isytimal dari lafal sebelumnya dengan mengulangi huruf jar (yaitu anak cucu mereka) maksudnya Dia mengeluarkan sebagian mereka dari tulang sulbi sebagian lainnya yang berasal dari sulbi Nabi Adam secara turun-temurun, sebagaimana sekarang mereka beranak-pinak mirip dengan jagung di daerah Nu`man sewaktu hari Arafah/musim jagung. Allah menetapkan kepada mereka bukti-bukti yang menunjukkan ketuhanan-Nya serta Dia memberinya akal (dan Allah mengambil kesaksian terhadap jiwa mereka) seraya berfirman, (\"Bukankah Aku ini Tuhanmu?\" Mereka menjawab, \"Betul.) Engkau adalah Tuhan kami (kami menjadi saksi.\") yang demikian itu. Kesaksian itu supaya (tidak) jangan (kamu mengatakan) dengan memakai ya dan ta pada dua tempat, yakni orang-orang kafir (di hari kiamat kelak, \"Sesungguhnya kami terhadap hal-hal ini) yakni keesaan Tuhan (adalah orang-orang yang lalai.\") kami tidak mengetahuinya.",[["وَإِذْ","And when"],["أَخَذَ","(was) taken"],["رَبُّكَ","(by) your Lord"],["مِنۢ","from"],["بَنِىٓ","(the) Children"],["ءَادَمَ","(of) Adam "],["مِن","from"],["ظُهُورِهِمْ","their loins "],["ذُرِّيَّتَهُمْ","their descendants"],["وَأَشْهَدَهُمْ","and made them testify"],["عَلَىٰٓ","over"],["أَنفُسِهِمْ","themselves"],["أَلَسْتُ","Am I not"],["بِرَبِّكُمْ ۖ","your Lord"],["قَالُوا۟","They said"],["بَلَىٰ ۛ","Yes"],["شَهِدْنَآ ۛ","we have testified"],["أَن","Lest"],["تَقُولُوا۟","you say"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["إِنَّا","Indeed"],["كُنَّا","we were"],["عَنْ","about"],["هَـٰذَا","this"],["غَـٰفِلِينَ","unaware"]]],"1127":["(Atau agar kamu tidak mengatakan, \"Sesungguhnya orang-orang tua kami telah mempersekutukan Tuhan sejak dahulu) dimaksud sebelum kami (sedangkan kami ini adalah anak-anak keturunan yang datang sesudah mereka) maka kami hanya mengikut mereka (Maka apakah Engkau akan membinasakan kami) Engkau akan mengazab kami (karena perbuatan orang-orang yang sesat dahulu?\") dari kalangan orang-orang tua kami yang pertama kali melakukan kemusyrikan. Kesimpulan pengertian dari ayat ini bahwa mereka tidak mungkin berhujah dengan alasan itu sedangkan mereka telah melakukan kesaksian terhadap diri mereka sendiri tentang keesaan Tuhan itu. Penuturan tentang hal ini melalui lisan pemilik mukjizat/Nabi Muhammad saw. kedudukannya sama dengan penuturan terhadap jiwa manusia semuanya.",[["أَوْ","Or"],["تَقُولُوٓا۟","you say"],["إِنَّمَآ","Only"],["أَشْرَكَ","partners (were) associated (with Allah)"],["ءَابَآؤُنَا","(by) our forefathers"],["مِن","from"],["قَبْلُ","before (us)"],["وَكُنَّا","and we are"],["ذُرِّيَّةًۭ","descendants"],["مِّنۢ","from"],["بَعْدِهِمْ ۖ","after them"],["أَفَتُهْلِكُنَا","So will You destroy us"],["بِمَا","for what"],["فَعَلَ","did"],["ٱلْمُبْطِلُونَ","the falsifiers"]]],"1128":["(Dan demikianlah Kami menjelaskan ayat-ayat itu) Kami menerangkan seperti apa yang telah Kami jelaskan di dalam perjanjian kesaksian supaya mereka memikirkannya (agar mereka kembali) dari kekafiran mereka kepada kebenaran.",[["وَكَذَٰلِكَ","And thus"],["نُفَصِّلُ","We explain"],["ٱلْـَٔايَـٰتِ","the Verses"],["وَلَعَلَّهُمْ","so that they may"],["يَرْجِعُونَ","return"]]],"1129":["(Dan bacakanlah) hai Muhammad (kepada mereka) yakni orang-orang Yahudi (berita) kabar (orang yang telah Kami berikan kepadanya ayat-ayat Kami, pengetahuan tentang isi Alkitab, kemudian dia melepaskan diri dari ayat-ayat itu) maksudnya ia keluar darinya dengan membawa kekafirannya, sebagaimana seekor ular keluar dari kulitnya, orang yang dimaksud ialah Bal`am bin Ba`ura salah seorang ulama terkemuka Bani Israel. Ia diminta agar mendoakan Musa celaka dan untuk itu diberi hadiah, dia mendoakan hal itu tetapi doanya itu menyebabkan senjata makan tuan akhirnya lidahnya menjulur sampai ke dadanya (lalu dia diikuti oleh setan) setan dapat menggodanya sehingga jadilah ia temannya (maka jadilah ia termasuk orang-orang yang sesat).",[["وَٱتْلُ","And recite"],["عَلَيْهِمْ","to them"],["نَبَأَ","(the) story"],["ٱلَّذِىٓ","(of the) one whom"],["ءَاتَيْنَـٰهُ","We gave [him]"],["ءَايَـٰتِنَا","Our Verses"],["فَٱنسَلَخَ","but he detached"],["مِنْهَا","[from] them"],["فَأَتْبَعَهُ","so followed him"],["ٱلشَّيْطَـٰنُ","the Shaitaan"],["فَكَانَ","and he became"],["مِنَ","of"],["ٱلْغَاوِينَ","those gone astray"]]],"1130":["(Dan kalau Kami menghendaki, sesungguhnya Kami tinggikan dia) kepada derajat para ulama (dengan ayat-ayat itu) seumpamanya Kami memberikan taufik/kekuatan kepadanya untuk mengamalkan ayat-ayat itu (tetapi dia cenderung) yaitu lebih menyukai (kepada tanah) yakni harta benda dan duniawi (dan menurutkan hawa nafsunya yang rendah) dalam doa yang dilakukannya, akhirnya Kami balik merendahkan derajatnya. (Maka perumpamaannya) ciri khasnya (seperti anjing jika kamu menghalaunya) mengusir dan menghardiknya (diulurkannya lidahnya) lidahnya menjulur (atau) jika (kamu membiarkannya dia mengulurkan lidahnya juga) sedangkan sifat seperti itu tidak terdapat pada hewan-hewan selain anjing. Kedua jumlah syarat menjadi hal, ia menjulurkan lidahnya dalam keadaan terhina dalam segala kondisi. Maksudnya penyerupaan/tasybih ini ialah mengumpamakan dalam hal kerendahan dan kehinaan dengan qarinah adanya fa yang memberikan pengertian tertib dengan kalimat sebelumnya, yakni kecenderungan terhadap duniawi dan mengikuti hawa nafsu rendahnya, juga karena adanya qarinah/bukti firman-Nya, (Demikian itulah) perumpamaan itulah (perumpamaan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah kisah-kisah itu) kepada orang-orang Yahudi (agar mereka berpikir) agar mereka mau memikirkannya hingga mereka mau beriman.",[["وَلَوْ","And if"],["شِئْنَا","We willed"],["لَرَفَعْنَـٰهُ","surely, We (could) have raised him"],["بِهَا","with these"],["وَلَـٰكِنَّهُۥٓ","[and] but he"],["أَخْلَدَ","adhered"],["إِلَى","to"],["ٱلْأَرْضِ","the earth"],["وَٱتَّبَعَ","and followed"],["هَوَىٰهُ ۚ","his (vain) desires"],["فَمَثَلُهُۥ","So his example"],["كَمَثَلِ","(is) like (the) example"],["ٱلْكَلْبِ","(of) the dog"],["إِن","if"],["تَحْمِلْ","you attack"],["عَلَيْهِ","[on] him"],["يَلْهَثْ","he lolls out his tongue"],["أَوْ","or"],["تَتْرُكْهُ","if you leave him"],["يَلْهَث ۚ","he lolls out his tongue"],["ذَّٰلِكَ","That"],["مَثَلُ","(is the) example"],["ٱلْقَوْمِ","(of) the people"],["ٱلَّذِينَ","who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا ۚ","[in] Our Signs"],["فَٱقْصُصِ","So relate"],["ٱلْقَصَصَ","the story"],["لَعَلَّهُمْ","so that they may"],["يَتَفَكَّرُونَ","reflect"]]],"1131":["(Amat buruklah) amat jeleklah (perumpamaan suatu kaum) yaitu perumpamaan kaum itu (yaitu orang-orang yang mendustakan ayat-ayat Kami dan kepada diri mereka sendirilah mereka berbuat lalim) dengan mendustakan ayat-ayat itu.",[["سَآءَ","Evil"],["مَثَلًا","(as) an example"],["ٱلْقَوْمُ","(are) the people"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["وَأَنفُسَهُمْ","and themselves"],["كَانُوا۟","they used to"],["يَظْلِمُونَ","wrong"]]],"1132":["(Barang siapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk dan barang siapa yang disesatkan Allah, maka merekalah orang-orang yang merugi).",[["مَن","Whoever"],["يَهْدِ","(is) guided"],["ٱللَّهُ","(by) Allah"],["فَهُوَ","then he"],["ٱلْمُهْتَدِى ۖ","(is) the guided one"],["وَمَن","while whoever"],["يُضْلِلْ","He lets go astray"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْخَـٰسِرُونَ","(are) the losers"]]],"1133":["(Dan sesungguhnya Kami jadikan) Kami ciptakan (untuk isi neraka Jahanam kebanyakan dari jin dan manusia, mereka mempunyai hati tetapi tidak dipergunakan untuk memahami ayat-ayat Allah) yakni perkara hak (dan mereka mempunyai mata tetapi tidak dipergunakannya untuk melihat tanda-tanda kekuasaan Allah) yaitu bukti-bukti yang menunjukkan kekuasaan Allah dengan penglihatan yang disertai pemikiran (dan mereka mempunyai telinga tetapi tidak dipergunakannya untuk mendengar ayat-ayat Allah) ayat-ayat Allah dan nasihat-nasihat-Nya dengan pendengaran yang disertai pemikiran dan ketaatan (mereka itu sebagai binatang ternak) dalam hal tidak mau mengetahui, melihat dan mendengar (bahkan mereka lebih sesat) dari hewan ternak itu sebab hewan ternak akan mencari hal-hal yang bermanfaat bagi dirinya dan ia akan lari dari hal-hal yang membahayakan dirinya tetapi mereka itu berani menyuguhkan dirinya ke dalam neraka dengan menentang (mereka itulah orang-orang yang lalai)",[["وَلَقَدْ","And certainly"],["ذَرَأْنَا","We have created"],["لِجَهَنَّمَ","for Hell"],["كَثِيرًۭا","many"],["مِّنَ","of"],["ٱلْجِنِّ","the jinn"],["وَٱلْإِنسِ ۖ","and men"],["لَهُمْ","For them"],["قُلُوبٌۭ","(are) hearts"],["لَّا","(but) not"],["يَفْقَهُونَ","they understand"],["بِهَا","with them"],["وَلَهُمْ","and for them"],["أَعْيُنٌۭ","(are) eyes"],["لَّا","(but) not"],["يُبْصِرُونَ","they see"],["بِهَا","with them"],["وَلَهُمْ","and for them"],["ءَاذَانٌۭ","(are) ears"],["لَّا","(but) not"],["يَسْمَعُونَ","they hear"],["بِهَآ ۚ","with them"],["أُو۟لَـٰٓئِكَ","Those"],["كَٱلْأَنْعَـٰمِ","(are) like cattle"],["بَلْ","nay"],["هُمْ","they"],["أَضَلُّ ۚ","(are) more astray"],["أُو۟لَـٰٓئِكَ","Those "],["هُمُ","they"],["ٱلْغَـٰفِلُونَ","(are) the heedless"]]],"1134":["(Allah mempunyai asma-asma yang baik) yang sembilan puluh sembilan, demikianlah telah disebutkan oleh hadis. Al-husna adalah bentuk muannats dari al-ahsan (maka bermohonlah kepada-Nya) sebutkanlah Dia olehmu (dengan menyebut nama-nama-Nya itu dan tinggalkanlah) maksudnya biarkanlah (orang-orang yang menyimpang dari kebenaran) berasal dan kata alhada dan lahada, yang artinya mereka menyimpang dari perkara yang hak (dalam menyebut nama-nama-Nya) artinya mereka mengambil nama-nama tersebut untuk disebutkan kepada sesembahan-sesembahan mereka, seperti nama Latta yang berakar dari lafal Allah, dan Uzzaa yang berakar dari kata Al-Aziiz, dan Manaat yang berakar dari kata Al-Mannaan (nanti mereka akan mendapat balasan) kelak di akhirat sebagai pembalasannya (terhadap apa yang telah mereka kerjakan) ketentuan ini sebelum turunnya ayat perintah berperang.",[["وَلِلَّهِ","And for Allah"],["ٱلْأَسْمَآءُ","(are) the names "],["ٱلْحُسْنَىٰ","the most beautiful"],["فَٱدْعُوهُ","so invoke Him"],["بِهَا ۖ","by them"],["وَذَرُوا۟","And leave"],["ٱلَّذِينَ","those who"],["يُلْحِدُونَ","deviate"],["فِىٓ","concerning"],["أَسْمَـٰٓئِهِۦ ۚ","His names"],["سَيُجْزَوْنَ","They will be recompensed"],["مَا","for what"],["كَانُوا۟","they used to"],["يَعْمَلُونَ","do"]]],"1135":["(Dan di antara orang-orang yang Kami ciptakan ada umat yang memberi petunjuk dengan hak, dan dengan yang hak itu pula mereka menjalankan keadilan) mereka adalah umat Muhammad saw. sebagaimana yang telah dijelaskan oleh hadis.",[["وَمِمَّنْ","And of (those) whom"],["خَلَقْنَآ","We have created"],["أُمَّةٌۭ","(is) a nation"],["يَهْدُونَ","who guides"],["بِٱلْحَقِّ","with the truth"],["وَبِهِۦ","and thereby"],["يَعْدِلُونَ","they establish justice"]]],"1136":["(Dan orang-orang yang mendustakan ayat-ayat Kami) yakni Alquran, dari kalangan penduduk Mekah (nanti Kami akan menarik mereka secara berangsur-angsur) Kami akan mengazab mereka sedikit demi sedikit (dengan cara yang tidak mereka ketahui).",[["وَٱلَّذِينَ","But those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا","Our Signs"],["سَنَسْتَدْرِجُهُم","We will gradually lead them"],["مِّنْ","from"],["حَيْثُ","where"],["لَا","not"],["يَعْلَمُونَ","they know"]]],"1137":["(Dan Aku memberi tangguh kepada mereka) Kami menangguhkan mereka (Sesungguhnya rencana-Ku amat tangguh) amat keras dan tidak bisa ditahan.",[["وَأُمْلِى","And I will give respite"],["لَهُمْ ۚ","to them"],["إِنَّ","Indeed"],["كَيْدِى","My plan"],["مَتِينٌ","(is) firm"]]],"1138":["(Apakah mereka tidak memikirkan) kemudian mereka dapat mengetahui (bahwa teman mereka) yaitu Muhammad saw. (tidak berpenyakit gila) bukanlah kurang akal (tidak lain) (dia hanyalah seorang pemberi peringatan lagi pemberi penjelasan) yang jelas peringatannya.",[["أَوَلَمْ","Do not"],["يَتَفَكَّرُوا۟ ۗ","they reflect"],["مَا","Not"],["بِصَاحِبِهِم","in their companion"],["مِّن","[of]"],["جِنَّةٍ ۚ","(is) any madness"],["إِنْ","Not"],["هُوَ","he"],["إِلَّا","(is) but"],["نَذِيرٌۭ","a warner"],["مُّبِينٌ","clear"]]],"1139":["(Dan apakah mereka tidak memperhatikan kerajaan) kekuasaan (langit dan bumi dan) di dalam (segala sesuatu yang diciptakan Allah) merupakan penjelasan dari apa yang sebelumnya, dengan hal itu mereka menyimpulkan tentang kekuasaan dan keesaan penciptanya (dan bahwasanya) sehubungan dengan (kemungkinan telah dekatnya) (kebinasaan mereka?) kemudian mereka mati dalam keadaan kafir, lalu mereka dimasukkan ke dalam neraka. Mengapa mereka tidak bersegera untuk beriman. (Maka kepada berita manakah lagi sesudahnya) yakni sesudah berita Alquran (mereka akan beriman?)",[["أَوَلَمْ","Do not"],["يَنظُرُوا۟","they look"],["فِى","in"],["مَلَكُوتِ","(the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and what"],["خَلَقَ","has (been) created"],["ٱللَّهُ","(by) Allah"],["مِن","of"],["شَىْءٍۢ","(every)thing"],["وَأَنْ","and that"],["عَسَىٰٓ","perhaps"],["أَن","[that]"],["يَكُونَ","has"],["قَدِ","verily"],["ٱقْتَرَبَ","come near "],["أَجَلُهُمْ ۖ","their term"],["فَبِأَىِّ","So in what"],["حَدِيثٍۭ","statement"],["بَعْدَهُۥ","after this"],["يُؤْمِنُونَ","will they believe"]]],"1140":["(Barang siapa yang Allah sesatkan, maka baginya tak ada orang yang akan memberi petunjuk. Dan Allah membiarkan mereka) dengan memakai ya dan nun serta dirafa`kan sebagai jumlah isti'naf/permulaan; sedangkan apabila dijazamkan maka diathafkan secara mahall kepada lafal sesudah fa (terombang-ambing dalam kesesatan) mereka terombang-ambing dalam keadaan bingung.",[["مَن","Whoever"],["يُضْلِلِ","(is) let go astray"],["ٱللَّهُ","(by) Allah"],["فَلَا","then (there is) no"],["هَادِىَ","guide"],["لَهُۥ ۚ","for him"],["وَيَذَرُهُمْ","And He leaves them"],["فِى","in"],["طُغْيَـٰنِهِمْ","their transgression"],["يَعْمَهُونَ","wandering blindly"]]],"1141":["(Mereka menanyakan kepadamu) yaitu mereka penduduk kota Mekah (tentang kiamat,) tentang hari akhir (\"Bilakah) kapan (terjadinya?\" Katakanlah,) kepada mereka (\"Sesungguhnya pengetahuan tentang kiamat itu) bila terjadinya (adalah pada sisi Tuhanku; tidak seorang pun yang dapat menjelaskan) menerangkan (waktu kedatangannya) huruf lam bermakna fii (selain Dia. Kiamat itu amat berat) amat besar peristiwanya (yang di langit dan di bumi) amat berat dirasakan oleh penduduk keduanya mengingat kengerian huru-haranya. (Kiamat itu tidak akan datang kepadamu melainkan dengan tiba-tiba.\") secara sekonyong-konyong (Mereka bertanya kepadamu seolah-olah kamu benar-benar mengetahui) terlalu berlebihan di dalam bertanya (tentang kiamat itu) sehingga engkau memberitahukan tentangnya. (Katakanlah, \"Sesungguhnya pengetahuan tentang kiamat itu adalah di sisi Allah) merupakan pengukuhan sebelumnya (tetapi kebanyakan manusia tidak mengetahui.\") pengetahuan mengenai kiamat itu hanya ada di sisi Allah swt.",[["يَسْـَٔلُونَكَ","They ask you"],["عَنِ","about"],["ٱلسَّاعَةِ","the Hour"],["أَيَّانَ","when will be"],["مُرْسَىٰهَا ۖ","its appointed time"],["قُلْ","Say"],["إِنَّمَا","Only"],["عِلْمُهَا","its knowledge"],["عِندَ","(is) with"],["رَبِّى ۖ","my Lord"],["لَا","no (one)"],["يُجَلِّيهَا","can reveal [it]"],["لِوَقْتِهَآ","its time"],["إِلَّا","except"],["هُوَ ۚ","Him"],["ثَقُلَتْ","It lays heavily"],["فِى","in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["لَا","Not"],["تَأْتِيكُمْ","will it come to you"],["إِلَّا","but"],["بَغْتَةًۭ ۗ","suddenly"],["يَسْـَٔلُونَكَ","They ask you"],["كَأَنَّكَ","as if you"],["حَفِىٌّ","(were) well informed"],["عَنْهَا ۖ","about it"],["قُلْ","Say"],["إِنَّمَا","Only"],["عِلْمُهَا","its knowledge"],["عِندَ","(is) with"],["ٱللَّهِ","Allah"],["وَلَـٰكِنَّ","but"],["أَكْثَرَ","most"],["ٱلنَّاسِ","(of) the people"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1142":["(Katakanlah, \"Aku tidak berkuasa menarik kemanfaatan bagi diriku sendiri) untuk mendapatkannya (dan tidak pula menolak kemudaratan) mampu menolaknya (kecuali yang dikehendaki Allah. Dan sekiranya aku mengetahui yang gaib) apa-apa yang gaib dariku (tentulah aku membuat kebaikan sebanyak-banyaknya dan aku tidak akan ditimpa kemudaratan) berupa kemiskinan dan lain sebagainya karena sebelumnya aku telah bersiap-siap menghadapinya dengan cara menghindari kemudaratan-kemudaratan itu (tidak lain) (aku ini hanyalah pemberi peringatan) dengan neraka bagi orang-orang kafir (dan pembawa berita gembira) dengan surga (bagi orang-orang yang beriman\").",[["قُل","Say"],["لَّآ","Not"],["أَمْلِكُ","I have power"],["لِنَفْسِى","for myself"],["نَفْعًۭا","(to) benefit"],["وَلَا","and no"],["ضَرًّا","(power to) harm"],["إِلَّا","except"],["مَا","what"],["شَآءَ","wills"],["ٱللَّهُ ۚ","Allah"],["وَلَوْ","And if"],["كُنتُ","I would"],["أَعْلَمُ","know"],["ٱلْغَيْبَ","(of) the unseen"],["لَٱسْتَكْثَرْتُ","surely I could have multiplied"],["مِنَ","of"],["ٱلْخَيْرِ","the good"],["وَمَا","and not"],["مَسَّنِىَ","(could) have touched me"],["ٱلسُّوٓءُ ۚ","the evil"],["إِنْ","Not"],["أَنَا۠","(am) I"],["إِلَّا","except"],["نَذِيرٌۭ","a warner"],["وَبَشِيرٌۭ","and a bearer of good tidings"],["لِّقَوْمٍۢ","to a people"],["يُؤْمِنُونَ","who believe"]]],"1143":["(Dialah) Allahlah (yang menciptakan kamu dari diri yang satu) yaitu Adam (dan Dia menjadikan) Dia menciptakan (daripadanya istrinya) yakni Hawa (agar dia merasa tenang) Adam menjimaknya (istrinya itu mengandung kandungan yang ringan) berupa air mani (dan teruslah dia merasa ringan) masih bisa berjalan ke sana dan kemari mengingat ringannya kandungan (kemudian tatkala dia merasa berat) anak yang ada dalam perutnya makin membesar, kemudian ia merasa khawatir bahwa kandungannya itu nanti berupa hewan (keduanya bermohon kepada Allah Tuhannya seraya berkata, \"Sesungguhnya jika Engkau memberi kami) anak (yang saleh) yang sempurna (tentulah kami termasuk orang-orang yang bersyukur.\") kepada-Mu atas karunia itu.",[["۞ هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["خَلَقَكُم","created you"],["مِّن","from"],["نَّفْسٍۢ","a soul"],["وَٰحِدَةٍۢ","single"],["وَجَعَلَ","and made"],["مِنْهَا","from it"],["زَوْجَهَا","its mate"],["لِيَسْكُنَ","that he might live"],["إِلَيْهَا ۖ","with her"],["فَلَمَّا","And when"],["تَغَشَّىٰهَا","he covers her"],["حَمَلَتْ","she carries"],["حَمْلًا","a burden"],["خَفِيفًۭا","light"],["فَمَرَّتْ","and continues"],["بِهِۦ ۖ","with it"],["فَلَمَّآ","But when"],["أَثْقَلَت","she grows heavy"],["دَّعَوَا","they both invoke"],["ٱللَّهَ","Allah"],["رَبَّهُمَا","their Lord"],["لَئِنْ","If"],["ءَاتَيْتَنَا","You give us"],["صَـٰلِحًۭا","a righteous (child)"],["لَّنَكُونَنَّ","surely we will be"],["مِنَ","among"],["ٱلشَّـٰكِرِينَ","the thankful"]]],"1144":["(Tatkala Allah memberi kepada keduanya) seorang anak (yang saleh, maka keduanya menjadikan sekutu bagi Allah) dalam suatu qiraat dibaca dengan dikasrahkan syinnya dan tanwin pada huruf akhirnya; yakni sekutu (tentang anak yang dianugerahkan-Nya kepada mereka berdua) dengan menamakannya Abdul Harits, sedangkan tidak boleh seorang hamba menjadi hamba selain kepada Allah. Yang dimaksud dalam penyekutuan di sini bukanlah dalam masalah ubudiah/ibadah, karena Nabi Adam telah dimaksum dari hal semacam itu. Samurah telah meriwayatkan dari Nabi saw. yang pernah bersabda bahwa ketika Hawa melahirkan seorang anak, iblis bertawaf mengelilingi Siti Hawa; sebelumnya anak Siti Hawa belum pernah ada yang hidup, kemudian iblis berkata kepadanya, \"Namakanlah dia anakmu yang baru lahir itu Abdul Harits, maka ia kelak akan hidup.\" Anak itu ternyata dapat hidup, hal itu terjadi karena ada saran dari setan dan perintah darinya, demikianlah menurut apa yang diriwayatkan oleh Al-Hakim. Al-Hakim mengatakan bahwa hadis ini sahih; Tirmizi mengatakan bahwa predikat hadis ini hasan gharib (Maka Maha Tinggi Allah dari apa yang mereka persekutukan) yakni penduduk Mekah dengan menjadikan berhala-berhala sebagai sesembahan mereka. Jumlah ayat ini merupakan musabbab atau penyebab, dan diathafkan kepada lafal khalaqakum, dan di antara sabab dengan musababnya terhadap jumlah mu`taridhah.",[["فَلَمَّآ","But when"],["ءَاتَىٰهُمَا","He gives them"],["صَـٰلِحًۭا","a good, (child)"],["جَعَلَا","they make"],["لَهُۥ","for Him"],["شُرَكَآءَ","partners"],["فِيمَآ","in what"],["ءَاتَىٰهُمَا ۚ","He has given them"],["فَتَعَـٰلَى","But exalted"],["ٱللَّهُ","(is) Allah"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate (with Him)"]]],"1145":["(Apakah mereka mempersekutukan) Allah dalam ibadah (dengan berhala-berhala yang tak dapat menciptakan sesuatu pun? Sedangkan berhala-berhala itu sendiri buatan orang).",[["أَيُشْرِكُونَ","Do they associate"],["مَا","what"],["لَا","(can) not"],["يَخْلُقُ","create"],["شَيْـًۭٔا","anything"],["وَهُمْ","and they"],["يُخْلَقُونَ","are created"]]],"1146":["(Dan berhala-berhala itu terhadap mereka tidak dapat) terhadap para pengabdinya (memberikan pertolongan, dan kepada dirinya sendiri pun berhala-berhala itu tidak dapat memberi pertolongan) tidak dapat mencegah orang yang bermaksud merusak mereka, apakah orang itu mau memecahkannya atau mau berbuat yang lain. Istifham/kata tanya di sini mempunyai pengertian untuk mencemoohkan.",[["وَلَا","And not"],["يَسْتَطِيعُونَ","they are able"],["لَهُمْ","to (give) them"],["نَصْرًۭا","any help"],["وَلَآ","and not"],["أَنفُسَهُمْ","themselves"],["يَنصُرُونَ","can they help"]]],"1147":["(Dan jika kamu menyerunya) menyeru berhala-berhala itu (untuk memberi petunjuk kepadamu, tidaklah berhala-berhala itu dapat memperkenankan seruanmu) dengan memakai takhfif dan tasydid (sama saja hasilnya buat kamu menyeru mereka) untuk meminta petunjuk (atau pun kamu berdiam diri) tidak menyeru mereka, maka mereka pasti tidak dapat memenuhi permintaanmu karena mereka tidak dapat mendengar.",[["وَإِن","And if"],["تَدْعُوهُمْ","you call them"],["إِلَى","to"],["ٱلْهُدَىٰ","the guidance"],["لَا","not"],["يَتَّبِعُوكُمْ ۚ","will they follow you"],["سَوَآءٌ","(It is) same"],["عَلَيْكُمْ","for you"],["أَدَعَوْتُمُوهُمْ","whether you call them"],["أَمْ","or"],["أَنتُمْ","you"],["صَـٰمِتُونَ","remain silent"]]],"1148":["(Sesungguhnya berhala-berhala yang kamu seru) yang kamu sembah (selain Allah itu adalah makhluk yang lemah) hamba-hamba (yang serupa juga dengan kamu. Maka serulah berhala-berhala itu lalu biarkanlah mereka memperkenankan permintaanmu) doa kamu (jika kami memang orang-orang yang benar) dalam anggapanmu bahwa mereka adalah tuhan. Kemudian Allah menjelaskan tentang kelemahan berhala-berhala tersebut dan Dia menjelaskan pula bahwa justru para pengabdinyalah yang lebih utama dari berhala-berhala itu sendiri. Untuk itu Allah berfirman:",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those whom"],["تَدْعُونَ","you call"],["مِن","from"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["عِبَادٌ","(are) slaves"],["أَمْثَالُكُمْ ۖ","like you"],["فَٱدْعُوهُمْ","So invoke them"],["فَلْيَسْتَجِيبُوا۟","and let them respond"],["لَكُمْ","to you"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"1149":["(Apakah berhala-berhala itu mempunyai kaki yang dengan itu mereka dapat berjalan atau) bahkan apakah (mereka mempunyai tangan-tangan) bentuk jamak dari lafal yadun/tangan (yang dengan tangan-tangan itu mereka dapat memukul atau) bahkan apakah (mereka mempunyai mata yang dengan mata itu mereka dapat melihat atau) bahkan apakah (mereka mempunyai telinga yang dengan telinga itu mereka dapat mendengar?) kata tanya yang terdapat di dalam ayat ini menunjukkan makna ingkar. Yakni bahwa berhala-berhala itu tidak mempunyai sesuatu pun dari hal-hal tersebut seperti apa yang kamu sekalian miliki. Lalu mengapa kamu menyembahnya sedang diri kamu sendiri keadaannya jauh lebih baik daripada mereka. (Katakanlah) kepada mereka, hai Muhammad (\"Panggillah berhala-berhalamu yang kamu jadikan sekutu bagi Allah itu) untuk mencelakakanku (kemudian lakukanlah tipu-daya kepadaku tanpa memberi tangguh kepadaku\") memberi tenggang waktu karena aku tidak lagi memperdulikanmu.",[["أَلَهُمْ","Are for them"],["أَرْجُلٌۭ","feet"],["يَمْشُونَ","(to) walk"],["بِهَآ ۖ","with [it]"],["أَمْ","or"],["لَهُمْ","for them"],["أَيْدٍۢ","hands"],["يَبْطِشُونَ","(to) hold"],["بِهَآ ۖ","with [it]"],["أَمْ","or"],["لَهُمْ","for them"],["أَعْيُنٌۭ","eyes"],["يُبْصِرُونَ","(to) see"],["بِهَآ ۖ","with [it]"],["أَمْ","or"],["لَهُمْ","for them"],["ءَاذَانٌۭ","ears"],["يَسْمَعُونَ","(to) hear"],["بِهَا ۗ","with [it]"],["قُلِ","Say"],["ٱدْعُوا۟","Call"],["شُرَكَآءَكُمْ","your partners"],["ثُمَّ","then"],["كِيدُونِ","scheme against me"],["فَلَا","and (do) not"],["تُنظِرُونِ","give me respite"]]],"1150":["(Sesungguhnya pelindungku ialah Allah) yang mengurusi perkaraku (yang telah menurunkan Alkitab) Alquran (dan Dia melindungi orang-orang yang saleh) memeliharanya.",[["إِنَّ","Indeed"],["وَلِـِّۧىَ","my protector"],["ٱللَّهُ","(is) Allah"],["ٱلَّذِى","the One Who"],["نَزَّلَ","revealed"],["ٱلْكِتَـٰبَ ۖ","the Book"],["وَهُوَ","And He"],["يَتَوَلَّى","protects"],["ٱلصَّـٰلِحِينَ","the righteous"]]],"1151":["(Dan berhala-berhala yang kamu seru selain Allah tidaklah sanggup menolongmu, bahkan tidak dapat menolong dirinya sendiri) lalu mengapa aku mempedulikan keadaan mereka.",[["وَٱلَّذِينَ","And those whom"],["تَدْعُونَ","you invoke"],["مِن","from"],["دُونِهِۦ","besides Him"],["لَا","not"],["يَسْتَطِيعُونَ","they are able"],["نَصْرَكُمْ","(to) help you"],["وَلَآ","and not"],["أَنفُسَهُمْ","themselves"],["يَنصُرُونَ","can they help"]]],"1152":["(Dan jika kamu sekalian menyeru mereka) berhala-berhala itu (untuk memberi petunjuk, niscaya berhala-berhala tidak dapat mendengarnya. Dan kamu melihat mereka) berhala-berhala itu, hai Muhammad (memandang kepadamu) yakni, mereka berhadapan denganmu bagaikan orang yang sedang memandang (padahal mereka tidak dapat melihat).",[["وَإِن","And if"],["تَدْعُوهُمْ","you call them"],["إِلَى","to"],["ٱلْهُدَىٰ","the guidance"],["لَا","not"],["يَسْمَعُوا۟ ۖ","do they not"],["وَتَرَىٰهُمْ","And you see them"],["يَنظُرُونَ","looking"],["إِلَيْكَ","at you"],["وَهُمْ","but they "],["لَا","not"],["يُبْصِرُونَ","(do) they see"]]],"1153":["(Jadilah engkau pemaaf) mudah memaafkan di dalam menghadapi perlakuan orang-orang, dan jangan membalas (dan suruhlah orang mengerjakan makruf) perkara kebaikan (serta berpalinglah daripada orang-orang yang bodoh) janganlah engkau melayani kebodohan mereka.",[["خُذِ","Hold"],["ٱلْعَفْوَ","(to) forgiveness"],["وَأْمُرْ","and enjoin"],["بِٱلْعُرْفِ","the good"],["وَأَعْرِضْ","and turn away"],["عَنِ","from"],["ٱلْجَـٰهِلِينَ","the ignorant"]]],"1154":["(Dan jika) lafal immaa merupakan gabungan antara in syarthiah dan maa zaidah atau tambahan (kamu ditimpa suatu godaan setan) dimaksud jika setan memalingkan kamu dari apa yang kamu diperintahkan untuk melakukannya dengan suatu godaan (maka berlindunglah kepada Allah) sebagai jawab syarath sedangkan jawab amarnya dibuang, yaitu guna menolak setan daripada dirimu (sesungguhnya Allah Maha Mendengar) semua perkataan (lagi Maha Mengetahui) semua pekerjaan.",[["وَإِمَّا","And if"],["يَنزَغَنَّكَ","an evil suggestion comes to you"],["مِنَ","from"],["ٱلشَّيْطَـٰنِ","[the] Shaitaan"],["نَزْغٌۭ","[an evil suggestion]"],["فَٱسْتَعِذْ","then seek refuge"],["بِٱللَّهِ ۚ","in Allah"],["إِنَّهُۥ","Indeed, He"],["سَمِيعٌ","(is) All-Hearing"],["عَلِيمٌ","All-Knowing"]]],"1155":["(Sesungguhnya orang-orang yang bertakwa bila mereka ditimpa) terkena (was-was) menurut suatu qiraat dibaca thaifun bukan thaaifun, artinya sesuatu yang menimpa mereka (dari setan mereka ingat) akan siksa Allah dan pahala-Nya (maka ketika itu mereka melihat) perbedaan antara perkara yang hak dan yang batil lalu mereka kembali kepada jalan yang hak.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ٱتَّقَوْا۟","fear (Allah)"],["إِذَا","when"],["مَسَّهُمْ","touches them"],["طَـٰٓئِفٌۭ","an evil thought"],["مِّنَ","from"],["ٱلشَّيْطَـٰنِ","the Shaitaan"],["تَذَكَّرُوا۟","they remember (Allah)"],["فَإِذَا","and then"],["هُم","they"],["مُّبْصِرُونَ","(are) those who see (aright)"]]],"1156":["(Dan teman-teman mereka) yaitu teman-teman setan terdiri dari orang-orang kafir (membantu mereka) setan-setan itu (dalam menyesatkan kemudian) mereka (tidak henti-hentinya) di dalam menyesatkan dengan sikap penuh hati-hati sebagaimana orang-orang yang takwa pun berhati-hati terhadap godaan mereka.",[["وَإِخْوَٰنُهُمْ","But their brothers"],["يَمُدُّونَهُمْ","they plunge them"],["فِى","in"],["ٱلْغَىِّ","the error"],["ثُمَّ","then"],["لَا","not"],["يُقْصِرُونَ","they cease"]]],"1157":["(Dan apabila kamu tidak membawa kepada mereka) kepada penduduk Mekah (suatu ayat) seperti apa yang mereka minta (mereka berkata, \"Mengapa tidak) (kamu buat-buat ayat itu?\") artinya kamu buat sendiri ayat itu? (Katakanlah,) kepada mereka (\"Sesungguhnya aku hanya mengikut apa yang diwahyukan kepadaku dari Tuhanku) aku tidak berhak untuk mendatangkannya dari diriku sendiri. (Ini) Alquran ini (adalah bukti-bukti yang jelas) hujah-hujah (dari Tuhanmu, petunjuk dan rahmat bagi orang-orang yang beriman.\")",[["وَإِذَا","And when"],["لَمْ","not"],["تَأْتِهِم","you bring them"],["بِـَٔايَةٍۢ","a Sign"],["قَالُوا۟","they say"],["لَوْلَا","Why (have) not"],["ٱجْتَبَيْتَهَا ۚ","you devised it"],["قُلْ","Say"],["إِنَّمَآ","Only"],["أَتَّبِعُ","I follow"],["مَا","what"],["يُوحَىٰٓ","is revealed"],["إِلَىَّ","to me"],["مِن","from"],["رَّبِّى ۚ","my Lord"],["هَـٰذَا","This (is)"],["بَصَآئِرُ","enlightenment"],["مِن","from"],["رَّبِّكُمْ","your Lord"],["وَهُدًۭى","and guidance"],["وَرَحْمَةٌۭ","and mercy"],["لِّقَوْمٍۢ","for a people"],["يُؤْمِنُونَ","who believe"]]],"1158":["(Dan apabila dibacakan Alquran, maka dengarkanlah baik-baik dan perhatikanlah) jangan berbicara (agar kamu mendapat rahmat) ayat ini diturunkan sehubungan dengan perintah tidak boleh berbicara sewaktu khutbah Jumat yang diungkapkan oleh ayat ini dengan istilah Alquran, mengingat khutbah itu mengandung ayat-ayat Alquran. Menurut pendapat lain berkaitan dengan pembacaan Alquran secara mutlak.",[["وَإِذَا","And when"],["قُرِئَ","is recited"],["ٱلْقُرْءَانُ","the Quran"],["فَٱسْتَمِعُوا۟","then listen"],["لَهُۥ","to it"],["وَأَنصِتُوا۟","and pay attention"],["لَعَلَّكُمْ","so that you may"],["تُرْحَمُونَ","receive mercy"]]],"1159":["(Dan sebutlah nama Tuhanmu di dalam hatimu) secara diam-diam (dengan merendahkan diri) menghinakan diri (dan rasa takut) yakni takut terhadap-Nya (dan) lebih jelas lagi daripada diam-diam dengan (tidak mengeraskan suara) maksudnya pertengahan di antara diam-diam dan keras suara (di waktu pagi dan petang) pada permulaan siang hari dan pada akhir siang hari (dan janganlah kamu termasuk orang-orang yang lalai) daripada mengingat atau menyebut Allah.",[["وَٱذْكُر","And remember"],["رَّبَّكَ","your Lord"],["فِى","in"],["نَفْسِكَ","yourself"],["تَضَرُّعًۭا","humbly"],["وَخِيفَةًۭ","and (in) fear"],["وَدُونَ","and without"],["ٱلْجَهْرِ","the loudness"],["مِنَ","of"],["ٱلْقَوْلِ","[the] words"],["بِٱلْغُدُوِّ","in the mornings"],["وَٱلْـَٔاصَالِ","and (in) the evenings"],["وَلَا","And (do) not"],["تَكُن","be"],["مِّنَ","among"],["ٱلْغَـٰفِلِينَ","the heedless"]]],"1160":["(Sesungguhnya mereka yang berada di sisi Tuhanmu) yakni malaikat-malaikat-Nya (tidaklah merasa enggan) tidak takabur (untuk menyembah Allah dan mereka bertasbih kepada-Nya) menyucikan-Nya dari hal-hal yang tidak layak menjadi sifat-Nya (dan hanya kepada-Nyalah mereka bersujud) mereka secara khusus tunduk dan bersujud hanya kepada-Nya, maka jadilah kamu sekalian seperti mereka.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["عِندَ","(are) near"],["رَبِّكَ","your Lord"],["لَا","not"],["يَسْتَكْبِرُونَ","(do) they turn away in pride"],["عَنْ","from"],["عِبَادَتِهِۦ","His worship"],["وَيُسَبِّحُونَهُۥ","And they glorify Him"],["وَلَهُۥ","and to Him"],["يَسْجُدُونَ ۩","they prostrate"]]],"1161":["(Mereka menanyakan kepadamu) hai Muhammad (tentang harta rampasan) perang, siapakah yang berhak menerimanya (Katakanlah,) kepada mereka (\"Harta rampasan perang itu kepunyaan Allah dan rasul-Nya) harta rampasan perang itu terserah menurut kesukaan Allah dan rasul-Nya; kemudian Rasulullah saw. membagi-bagikan harta rampasan itu secara merata kepada mereka semuanya. Demikianlah menurut hadis yang diriwayatkan oleh Imam Al-Hakim di dalam kitab Al-Mustadrak (sebab itu bertakwalah kalian kepada Allah dan perbaikilah hubungan di antara sesamamu) yakni jalinlah kembali hubungan antara kalian dengan penuh kecintaan dan tinggalkanlah persengketaan (dan taatlah kalian kepada Allah dan rasul-Nya, jika kamu adalah orang-orang yang beriman.\") yang benar-benar beriman.",[["يَسْـَٔلُونَكَ","They ask you"],["عَنِ","about"],["ٱلْأَنفَالِ ۖ","the spoils of war"],["قُلِ","Say"],["ٱلْأَنفَالُ","The spoils of war"],["لِلَّهِ","(are) for Allah"],["وَٱلرَّسُولِ ۖ","and the Messenger"],["فَٱتَّقُوا۟","So fear"],["ٱللَّهَ","Allah"],["وَأَصْلِحُوا۟","and set right"],["ذَاتَ","that"],["بَيْنِكُمْ ۖ","(which is) between you"],["وَأَطِيعُوا۟","and obey"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥٓ","and His Messenger"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"1162":["(Sesungguhnya orang-orang yang beriman itu) yang sempurna keimanannya (adalah mereka yang apabila disebut Allah) yakni ancaman-Nya (gemetarlah) karena takut (hati mereka dan apabila dibacakan kepada mereka ayat-ayat-Nya bertambahlah keimanan mereka) kepercayaan mereka (dan kepada Tuhanlah mereka bertawakal) hanya kepada Rabblah mereka percaya bukan kepada selain-Nya.",[["إِنَّمَا","Only"],["ٱلْمُؤْمِنُونَ","the believers"],["ٱلَّذِينَ","(are) those who"],["إِذَا","when"],["ذُكِرَ","is mentioned"],["ٱللَّهُ","Allah"],["وَجِلَتْ","feel fear"],["قُلُوبُهُمْ","their hearts"],["وَإِذَا","and when"],["تُلِيَتْ","are recited"],["عَلَيْهِمْ","to them"],["ءَايَـٰتُهُۥ","His Verses"],["زَادَتْهُمْ","they increase them"],["إِيمَـٰنًۭا","(in) faith"],["وَعَلَىٰ","and upon"],["رَبِّهِمْ","their Lord"],["يَتَوَكَّلُونَ","they put their trust"]]],"1163":["(Yaitu orang-orang yang mendirikan salat) mereka menunaikannya sesuai dengan ketentuan-ketentuannya (dan sebagian dari apa yang telah Kami berikan kepada mereka) Kami anugerahkan kepada mereka (mereka menafkahkannya) demi taat kepada Allah.",[["ٱلَّذِينَ","Those who"],["يُقِيمُونَ","establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَمِمَّا","and out of what"],["رَزَقْنَـٰهُمْ","We have provided them"],["يُنفِقُونَ","they spend"]]],"1164":["(Itulah) orang-orang yang berciri khas seperti tadi (mereka orang-orang yang beriman dengan sebenar-benarnya) yang tidak diragukan lagi keimanannya. (Mereka akan memperoleh beberapa derajat ketinggian) kedudukan-kedudukan di surga (di sisi Tuhannya dan ampunan serta rezeki yang mulia) di surga.",[["أُو۟لَـٰٓئِكَ","Those "],["هُمُ","they are"],["ٱلْمُؤْمِنُونَ","the believers"],["حَقًّۭا ۚ","(in) truth"],["لَّهُمْ","For them"],["دَرَجَـٰتٌ","(are) ranks"],["عِندَ","with"],["رَبِّهِمْ","their Lord"],["وَمَغْفِرَةٌۭ","and forgiveness"],["وَرِزْقٌۭ","and a provision"],["كَرِيمٌۭ","noble"]]],"1165":["(Sebagaimana Tuhanmu menyuruhmu pergi dari rumahmu dengan kebenaran) jar dan majrur berta`alluq pada lafal akhraja (padahal sesungguhnya sebagian dari orang-orang yang beriman itu tidak menyukainya) yakni mereka tidak menyukai keluar bersama Nabi. Jumlah kalimat maa akhrajaka dan seterusnya merupakan keterangan keadaan dari huruf kaf yang terdapat pada lafal kamaa. Kemudian lafal kamaa akhrajaka berkedudukan menjadi khabar atau kalimat berita dari mubtada yang dibuang, yakni keadaan yang tidak mereka sukai adalah sewaktu engkau diminta keluar sedangkan mereka tidak menyukai hal itu, padahal itu baik untuk mereka, demikianlah keadaan mereka. Demikian itu karena Abu Sofyan yang datang membawa kafilah perdagangan dari negeri Syam, beritanya sampai kepada Nabi saw. Maka Nabi saw. segera keluar bersama para sahabat guna mencegah kafilah tersebut. Akan tetapi berita keberangkatannya diketahui oleh orang-orang Quraisy. Maka keluarlah Abu Jahal beserta pasukan perang kota Mekah untuk melindungi kafilahnya itu, mereka bersenjata lengkap dan banyak pasukannya. Abu Sofyan membawa kafilahnya mengikuti jalan tepi pantai sehingga selamatlah mereka dari cegatan kaum Muslimin. Lalu ada yang berkata kepada Abu Jahal, \"Mari kita kembali.\" Akan tetapi Abu Jahal menolak dan bahkan terus bermusyawarah dengan para sahabatnya; Nabi saw. bersabda kepada mereka, \"Sesungguhnya Allah swt. telah menjanjikan kepadaku kemenangan atas salah satu dari dua rombongan,\" yaitu rombongan Abu Sofyan atau rombongan Abu Jahal. Akhirnya mereka sepakat untuk memerangi pasukan yang bersenjata; tetapi sebagian dari kaum Mukminin tidak menyukai hal itu, mereka mengatakan, \"Kami masih belum siap untuk menghadapi hal itu,\" sebagaimana yang diungkapkan oleh firman-Nya berikut ini:",[["كَمَآ","As"],["أَخْرَجَكَ","brought you out"],["رَبُّكَ","your Lord"],["مِنۢ","from"],["بَيْتِكَ","your home"],["بِٱلْحَقِّ","in truth"],["وَإِنَّ","while indeed"],["فَرِيقًۭا","a party"],["مِّنَ","among"],["ٱلْمُؤْمِنِينَ","the believers"],["لَكَـٰرِهُونَ","certainly disliked"]]],"1166":["(Mereka membantahmu tentang kebenaran) yaitu tentang alternatif berperang (sesudah nyata) sesudah jelas bagi mereka bahwa mereka pasti menang (seolah-olah mereka dihalau kepada kematian sedang mereka melihat) kematian itu secara terang-terangan yang membuat mereka tidak senang kepadanya.",[["يُجَـٰدِلُونَكَ","They dispute with you"],["فِى","concerning"],["ٱلْحَقِّ","the truth"],["بَعْدَ مَا","after what"],["تَبَيَّنَ","was made clear"],["كَأَنَّمَا","as if"],["يُسَاقُونَ","they were driven"],["إِلَى","to"],["ٱلْمَوْتِ","[the] death"],["وَهُمْ","while they"],["يَنظُرُونَ","(were) looking"]]],"1167":["(Dan) ingatlah (ketika Allah menjanjikan kepadamu salah satu dari dua golongan) yakni rombongan kafilah atau pasukan bersenjata (bahwa salah satu dari dua golongan yang kamu hadapi adalah untukmu, sedangkan kamu menginginkan) kalian hanya menghendaki (bahwa golongan yang tidak mempunyai kekuatan senjatalah) golongan yang tidak mempunyai kekuatan dan persenjataan, yaitu golongan kafilah dagang (yang untukmu) mengingat pengawalnya sedikit dan persenjataannya pun tidak lengkap, berbeda dengan golongan pasukan bersenjata (dan Allah menghendaki untuk membenarkan yang benar) menampakkan yang benar (dengan ayat-ayat-Nya) yang dahulu melalui kemenangan Islam (dan memusnahkan orang-orang kafir) kekuatan mereka dengan mengalahkan mereka, maka Dia memerintahkan kalian untuk memerangi pasukan bersenjata mereka.",[["وَإِذْ","And when"],["يَعِدُكُمُ","promised you"],["ٱللَّهُ","Allah"],["إِحْدَى","one"],["ٱلطَّآئِفَتَيْنِ","(of) the two groups "],["أَنَّهَا","that it (would be)"],["لَكُمْ","for you "],["وَتَوَدُّونَ","and you wished"],["أَنَّ","that"],["غَيْرَ","(one) other than"],["ذَاتِ","that"],["ٱلشَّوْكَةِ","(of) the armed"],["تَكُونُ","would be"],["لَكُمْ","for you"],["وَيُرِيدُ","But intended"],["ٱللَّهُ","Allah"],["أَن","to"],["يُحِقَّ","justify"],["ٱلْحَقَّ","the truth"],["بِكَلِمَـٰتِهِۦ","by His words"],["وَيَقْطَعَ","and cut off"],["دَابِرَ","(the) roots"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"]]],"1168":["(Agar Allah menetapkan yang hak dan membatalkan) menghapus (kebatilan) yakni kekafiran (walaupun orang-orang yang berdosa itu tidak menyukainya) orang-orang musyrik tidak menyenangi hal itu.",[["لِيُحِقَّ","That He might justify"],["ٱلْحَقَّ","the truth"],["وَيُبْطِلَ","and prove false"],["ٱلْبَـٰطِلَ","the falsehood"],["وَلَوْ","even if"],["كَرِهَ","disliked (it)"],["ٱلْمُجْرِمُونَ","the criminals"]]],"1169":["(Ingatlah, ketika kamu memohon pertolongan Tuhanmu) ketika kamu meminta pertolongan dari-Nya untuk dapat mengalahkan orang-orang musyrik (lalu diperkenankan-Nya bagimu, \"Sesungguhnya Aku) sungguh Aku pasti (memberikan bantuan kepadamu) akan menolongmu (dengan mendatangkan seribu malaikat yang datang berturut-turut\") yakni mereka datang secara berturut-turut, sebagian dari mereka menyusul sebagian lainnya. Pada permulaannya Allah menjanjikan untuk mereka bantuan seribu malaikat, kemudian menjadi tiga ribu malaikat, hingga sampai lima ribu malaikat, seperti yang dijelaskan di dalam surah Ali Imran. Menurut suatu qiraat lafal alfun dibaca aalaf seperti aflas dalam bentuk jamak.",[["إِذْ","When"],["تَسْتَغِيثُونَ","you were seeking help"],["رَبَّكُمْ","(of) your Lord"],["فَٱسْتَجَابَ","and He answered"],["لَكُمْ","[to] you"],["أَنِّى","Indeed, I am"],["مُمِدُّكُم","going to reinforce you"],["بِأَلْفٍۢ","with a thousand"],["مِّنَ","of"],["ٱلْمَلَـٰٓئِكَةِ","the Angels"],["مُرْدِفِينَ","one after another"]]],"1170":["(Dan Allah tidak menjadikannya) bala bantuan tersebut (melainkan sebagian berita gembira dan agar hatimu menjadi tenteram karenanya. Dan kemenangan itu hanyalah dari sisi Allah. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana).",[["وَمَا","And not"],["جَعَلَهُ","(it was) made"],["ٱللَّهُ","(by) Allah"],["إِلَّا","but"],["بُشْرَىٰ","good tidings"],["وَلِتَطْمَئِنَّ","and so that might be at rest"],["بِهِۦ","with it"],["قُلُوبُكُمْ ۚ","your hearts"],["وَمَا","And (there is) no"],["ٱلنَّصْرُ","[the] victory"],["إِلَّا","except"],["مِنْ","from"],["عِندِ","[of]"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَزِيزٌ","(is) All-Mighty"],["حَكِيمٌ","All-Wise"]]],"1171":["(Ingatlah, ketika Allah menjadikan kamu mengantuk sebagai suatu penenteram) untuk menenteramkan hatimu dari rasa takut yang menimpa dirimu (daripada-Nya) Allah Yang Maha Tinggi (dan Allah menurunkan kepadamu hujan dari langit untuk menyucikan kamu dengan hujan itu) dari hadas dan jinabah itu (dan menghilangkan dari kamu gangguan-gangguan setan) godaan setan dari dirimu yang mengatakan bahwasanya jika kamu berada dalam jalan kebenaran, niscaya kamu tidak akan kehausan lagi berhadas sedang kaum musyrikin berada dekat air (dan untuk menguatkan) mengokohkan (hatimu) dalam keyakinan dan kesabaran (dan memperteguh dengannya telapak kakimu) agar telapak kakimu berdiri tegar di padang pasir.",[["إِذْ","When"],["يُغَشِّيكُمُ","He covered you"],["ٱلنُّعَاسَ","with [the] slumber"],["أَمَنَةًۭ","a security"],["مِّنْهُ","from Him"],["وَيُنَزِّلُ","and sent down"],["عَلَيْكُم","upon you"],["مِّنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["لِّيُطَهِّرَكُم","so that He may purify you"],["بِهِۦ","with it"],["وَيُذْهِبَ","and take away"],["عَنكُمْ","from you"],["رِجْزَ","evil (suggestions)"],["ٱلشَّيْطَـٰنِ","(of) the Shaitaan"],["وَلِيَرْبِطَ","And to strengthen"],["عَلَىٰ","[on]"],["قُلُوبِكُمْ","your hearts"],["وَيُثَبِّتَ","and make firm"],["بِهِ","with it"],["ٱلْأَقْدَامَ","your feet"]]],"1172":["(Ingatlah ketika Tuhanmu mewahyukan kepada para malaikat) yang diperbantukan kepada kaum Muslimin (\"Sesungguhnya Aku) bahwasanya Aku (bersama kamu) memberikan pertolongan dan bantuan (maka teguhkanlah pendirian orang-orang yang telah beriman) dengan memberikan pertolongan kepada mereka dan mengabarkan berita gembira. (Kelak Aku akan timpakan rasa ketakutan ke dalam hati orang-orang kafir) ketakutan yang sangat (maka penggallah leher mereka) kepala mereka (dan pancunglah tiap-tiap ujung jari mereka) ujung-ujung jari tangan dan kaki. Dikatakan bahwa dalam perang itu jika seseorang muslim hendak memukul kepala si kafir tiba-tiba kepala itu sudah jatuh menggelinding sendiri sebelum pedangnya sampai kepadanya. Dan Rasulullah saw. melempar mereka dengan segenggam batu kerikil, maka tidak ada seorang musyrik pun yang luput matanya dari lemparan batu kerikil itu, akhirnya mereka kalah.",[["إِذْ","When"],["يُوحِى","inspired"],["رَبُّكَ","your Lord"],["إِلَى","to"],["ٱلْمَلَـٰٓئِكَةِ","the Angels"],["أَنِّى","I am"],["مَعَكُمْ","with you"],["فَثَبِّتُوا۟","so strengthen"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟ ۚ","believed"],["سَأُلْقِى","I will cast"],["فِى","in"],["قُلُوبِ","(the) hearts"],["ٱلَّذِينَ","(of) those who"],["كَفَرُوا۟","disbelieved "],["ٱلرُّعْبَ","the terror"],["فَٱضْرِبُوا۟","so strike"],["فَوْقَ","above"],["ٱلْأَعْنَاقِ","the necks"],["وَٱضْرِبُوا۟","and strike"],["مِنْهُمْ","from them"],["كُلَّ","every"],["بَنَانٍۢ","fingertip[s]"]]],"1173":["(Yang demikian itu) azab yang menimpa mereka itu (adalah karena sesungguhnya mereka menentang) melawan (Allah dan rasul-Nya; dan barang siapa menentang Allah dan rasul-Nya, maka sesungguhnya Allah amat keras siksaan-Nya) terhadapnya.",[["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because they"],["شَآقُّوا۟","opposed"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ ۚ","and His Messenger"],["وَمَن","And whoever"],["يُشَاقِقِ","opposes"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["شَدِيدُ","(is) severe"],["ٱلْعِقَابِ","in [the] penalty"]]],"1174":["(Itulah) hukuman yang ditimpakan atasmu (maka rasakanlah hukuman itu) hai orang-orang kafir, sebagai hukuman di dunia (sesungguhnya bagi orang-orang yang kafir itu) kelak di hari kemudian (azab neraka\").",[["ذَٰلِكُمْ","That "],["فَذُوقُوهُ","So taste it"],["وَأَنَّ","And that"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["عَذَابَ","(is the) punishment"],["ٱلنَّارِ","(of) the Fire"]]],"1175":["(Hai orang-orang yang beriman, jika kamu bertemu dengan orang-orang yang kafir yang sedang menyerangmu) mereka menghimpun kekuatan dalam jumlah yang banyak sehingga mereka kelihatan seakan-akan merayap maju (maka janganlah kamu membelakangi mereka) dalam keadaan lari karena kalah.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe"],["إِذَا","When"],["لَقِيتُمُ","you meet"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["زَحْفًۭا","advancing"],["فَلَا","then (do) not"],["تُوَلُّوهُمُ","turn to them"],["ٱلْأَدْبَارَ","the backs"]]],"1176":["(Barang siapa yang membelakangi mereka di waktu itu) ketika berhadapan dengan mereka di medan peperangan (dalam keadaan mundur kecuali berbelok) mengelak (untuk siasat perang) dengan cara berpura-pura lari tetapi untuk tujuan menyerang (atau menggabungkan diri) menyatu (dengan pasukan yang lain) dengan pasukan kaum Muslimin lainnya meminta tolong kepada mereka (maka sesungguhnya orang itu kembali) pulang (dengan membawa kemurkaan dari Allah, dan tempatnya ialah neraka Jahanam. Dan amat buruklah tempat kembalinya) sejelek-jelek tempat kembali ialah neraka Jahanam. Keadaan ini khusus jika orang-orang kafir tidak makin bertambah lemah.",[["وَمَن","And whoever"],["يُوَلِّهِمْ","turns to them"],["يَوْمَئِذٍۢ","that day"],["دُبُرَهُۥٓ","his back"],["إِلَّا","except"],["مُتَحَرِّفًۭا","(as) a strategy"],["لِّقِتَالٍ","of war"],["أَوْ","or"],["مُتَحَيِّزًا","(to) join"],["إِلَىٰ","to"],["فِئَةٍۢ","a group"],["فَقَدْ","certainly"],["بَآءَ","(he has) incurred"],["بِغَضَبٍۢ","wrath"],["مِّنَ","of"],["ٱللَّهِ","Allah"],["وَمَأْوَىٰهُ","and his abode"],["جَهَنَّمُ ۖ","(is) Hell"],["وَبِئْسَ","a wretched"],["ٱلْمَصِيرُ","destination"]]],"1177":["(Maka yang sebenarnya bukan kamu yang membunuh mereka) di Badar dengan kekuatanmu (akan tetapi Allahlah yang membunuh mereka) dengan melalui pertolongan-Nya yang Dia limpahkan kepada kalian (dan bukan kamu yang melempar) mata kaum musyrikin, hai Muhammad (ketika kamu melempar) dengan batu kerikil, sebab sekali lempar dengan segenggam batu kerikil yang dilakukan oleh manusia tidak akan dapat memenuhi mata bala tentara yang begitu banyaknya (tetapi Allahlah yang melempar) dengan cara mengenakan lemparan itu kepada mereka; hal ini sengaja Dia lakukan guna mengalahkan orang-orang kafir (dan untuk memberi kemenangan kepada orang-orang mukmin dengan kemenangan) yakni anugerah (yang baik) yang dimaksud adalah ganimah/harta rampasan perang. (Sesungguhnya Allah Maha Mendengar) perkataan mereka (lagi Maha Mengetahui) tentang keadaan mereka.",[["فَلَمْ","And not"],["تَقْتُلُوهُمْ","you kill them"],["وَلَـٰكِنَّ","but"],["ٱللَّهَ","Allah"],["قَتَلَهُمْ ۚ","killed them"],["وَمَا","And not"],["رَمَيْتَ","you threw"],["إِذْ","when"],["رَمَيْتَ","you threw"],["وَلَـٰكِنَّ","but"],["ٱللَّهَ","Allah"],["رَمَىٰ ۚ","threw"],["وَلِيُبْلِىَ","and that He may test"],["ٱلْمُؤْمِنِينَ","the believers"],["مِنْهُ","from Him"],["بَلَآءً","(with) a trial"],["حَسَنًا ۚ","good"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَمِيعٌ","(is) All-Hearing"],["عَلِيمٌۭ","All-Knowing"]]],"1178":["(Itulah) kemenangan itu suatu hal yang nyata (dan sesungguhnya Allah melemahkan) membuat tidak berdaya (tipu daya orang-orang yang kafir).",[["ذَٰلِكُمْ","That (is the case)"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah (is)"],["مُوهِنُ","one who makes weak"],["كَيْدِ","(the) plan"],["ٱلْكَـٰفِرِينَ","(of) the disbelievers"]]],"1179":["(Jika kalian mencari keputusan) hai orang-orang kafir, yakni kamu sekalian meminta keputusan, di mana salah seorang dari kamu yaitu Abu Jahal mengatakan, \"Ya Allah! Siapakah dari kami yang paling memutuskan silaturahmi dan yang paling banyak melakukan hal-hal yang tidak dikenal pada kalangan kami, maka semoga Engkau membinasakannya (maka telah datang kepadamu keputusan) ketentuan binasanya orang-orang yang melakukan hal itu, mereka adalah Abu Jahal dan orang-orang yang terbunuh bersamanya, bukannya Nabi saw. dan kaum mukminin (dan jika kalian berhenti) dari perbuatan kafir dan memerangi Nabi saw. (maka itulah yang lebih baik bagi kalian; dan jika kalian kembali) untuk memerangi Nabi saw. (niscaya Kami kembali) untuk memberikan pertolongan kepada Nabi saw. atas kalian (dan tidak akan dapat mencukupi) menolak (angkatan perang kalian dari kalian) yakni golongan kalian (sesuatu bahaya pun biar pun angkatan perang itu banyak dan sesungguhnya Allah beserta orang-orang yang beriman) huruf inna dibaca kasrah sebagai jumlah isti`naf, dan dibaca anna dengan memperkirakan adanya huruf lam, bentuk lengkapnya ialah lama`al mu`miina.",[["إِن","If"],["تَسْتَفْتِحُوا۟","you ask for victory"],["فَقَدْ","then certainly"],["جَآءَكُمُ","has come to you"],["ٱلْفَتْحُ ۖ","the victory"],["وَإِن","And if"],["تَنتَهُوا۟","you desist"],["فَهُوَ","then it (is)"],["خَيْرٌۭ","good"],["لَّكُمْ ۖ","for you"],["وَإِن","but if"],["تَعُودُوا۟","you return"],["نَعُدْ","We will return (too)"],["وَلَن","And never"],["تُغْنِىَ","will avail"],["عَنكُمْ","you"],["فِئَتُكُمْ","your forces"],["شَيْـًۭٔا","anything"],["وَلَوْ","even if"],["كَثُرَتْ","(they are) numerous"],["وَأَنَّ","And that"],["ٱللَّهَ","Allah"],["مَعَ","(is) with"],["ٱلْمُؤْمِنِينَ","the believers"]]],"1180":["(Hai orang-orang yang beriman, taatlah kamu sekalian kepada Allah dan Rasul-Nya, dan janganlah kalian berpaling) memalingkan diri (daripada-Nya) dengan cara menentang perintah-Nya (sedang kalian mendengar) Alquran dan nasihat-nasihat-Nya.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe"],["أَطِيعُوا۟","Obey"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["وَلَا","And (do) not"],["تَوَلَّوْا۟","turn away"],["عَنْهُ","from him"],["وَأَنتُمْ","while you"],["تَسْمَعُونَ","hear"]]],"1181":["(Dan janganlah kalian menjadi sebagai orang-orang yang berkata, \"Kami mendengar; padahal mereka tidak mendengarkan) secara sadar dan penuh dengan pengertian, mereka adalah orang-orang munafik dan kaum musyrikin",[["وَلَا","And (do) not"],["تَكُونُوا۟","be"],["كَٱلَّذِينَ","like those who"],["قَالُوا۟","say"],["سَمِعْنَا","We heard"],["وَهُمْ","while they"],["لَا","(do) not"],["يَسْمَعُونَ","hear"]]],"1182":["(Sesungguhnya binatang, makhluk-makhluk yang seburuk-buruknya di sisi Allah ialah orang-orang yang tuli) tidak mau mendengarkan perkara yang hak (dan bisu) tidak mengucapkan perkara yang hak (yang tidak mengerti apa pun) tentang perkara yang hak.",[["۞ إِنَّ","Indeed"],["شَرَّ","worst"],["ٱلدَّوَآبِّ","(of) the living creatures"],["عِندَ","near"],["ٱللَّهِ","Allah"],["ٱلصُّمُّ","(are) the deaf"],["ٱلْبُكْمُ","the dumb "],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَعْقِلُونَ","use (their) intellect"]]],"1183":["(Kalau sekiranya Allah mengetahui kebaikan pada mereka) bakat yang baik di dalam mendengarkan perkara yang hak (tentulah Allah menjadikan mereka dapat mendengar) dengan pendengaran yang disertai pemahaman. (Dan jika Allah menjadikan mereka dapat mendengar) sebagai perumpamaan, karena Allah telah mengetahui bahwa tidak ada kebaikan dalam diri mereka (niscaya mereka pasti berpaling juga) dari perkara yang hak itu (sedangkan mereka memalingkan diri\") dari menerima perkara hak yang mereka dengar itu karena keras hati dan ingkar.",[["وَلَوْ","And if"],["عَلِمَ","(had) known"],["ٱللَّهُ","Allah"],["فِيهِمْ","in them"],["خَيْرًۭا","any good"],["لَّأَسْمَعَهُمْ ۖ","surely, He (would) have made them hear"],["وَلَوْ","And if"],["أَسْمَعَهُمْ","He had made them hear"],["لَتَوَلَّوا۟","surely they would have turned away"],["وَّهُم","while they"],["مُّعْرِضُونَ","(were) averse"]]],"1184":["(Hai orang-orang yang beriman, penuhilah seruan Allah dan seruan Rasul) dengan taat (apabila Rasul menyeru kamu pada suatu yang memberi kehidupan kepada kalian) berupa perkara agama sebab perkara agama merupakan penyebab bagi kehidupan yang kekal (dan ketahuilah oleh kalian bahwa sesungguhnya Allah menghalangi antara manusia dan hatinya) maka ia tidak dapat beriman atau kafir melainkan berdasarkan kehendak Allah (dan sesungguhnya kepada-Nyalah kamu akan dikumpulkan) Allah akan membalas semua amal perbuatan kalian.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["ٱسْتَجِيبُوا۟","Respond"],["لِلَّهِ","to Allah"],["وَلِلرَّسُولِ","and His Messenger"],["إِذَا","when"],["دَعَاكُمْ","he calls you"],["لِمَا","to what"],["يُحْيِيكُمْ ۖ","gives you life"],["وَٱعْلَمُوٓا۟","And know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["يَحُولُ","comes"],["بَيْنَ","(in) between"],["ٱلْمَرْءِ","a man"],["وَقَلْبِهِۦ","and his heart"],["وَأَنَّهُۥٓ","and that"],["إِلَيْهِ","to Him"],["تُحْشَرُونَ","you will be gathered"]]],"1185":["(Dan peliharalah diri kalian daripada siksaan) jika siksaan menimpa kalian (ia tidak khusus menimpa orang-orang yang lalim saja di antara kalian) bahkan siksaan itu merata kepada mereka dan selain mereka. Dan cara untuk memelihara diri supaya jangan tertimpa siksaan ialah membenci penyebabnya, yaitu perkara mungkar. (Dan ketahuilah bahwa Allah sangat keras siksaan-Nya) terhadap orang-orang yang melanggar perintah dan larangan-Nya.",[["وَٱتَّقُوا۟","And fear"],["فِتْنَةًۭ","a trial"],["لَّا","not"],["تُصِيبَنَّ","which will afflict"],["ٱلَّذِينَ","those who"],["ظَلَمُوا۟","do wrong"],["مِنكُمْ","among you"],["خَآصَّةًۭ ۖ","exclusively"],["وَٱعْلَمُوٓا۟","And know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["شَدِيدُ","(is) severe"],["ٱلْعِقَابِ","(in) the penalty"]]],"1186":["(Dan ingatlah hai para Muhajirin ketika kalian masih berjumlah sedikit lagi tertindas di muka bumi) yakni Mekah (kalian takut orang-orang Mekah akan menculik kalian) mengambil kalian dengan cepat (maka Allah memberi kalian tempat menetap) yaitu kota Madinah (dan didukung-Nya kalian) Dia membuat kalian menjadi kuat (dengan pertolongan-Nya) ketika perang Badar, yaitu melalui bantuan para malaikat (dan diberi-Nya kalian rezeki dari yang baik-baik) berupa ganimah (agar kalian bersyukur) terhadap nikmat-nikmat-Nya. Ayat ini diturunkan berkenaan dengan Abu Lubabah alias Marwan bin Abdul Munzir. Nabi saw. telah mengutusnya kepada orang-orang Bani Quraizhah dengan membawa pesan darinya, supaya mereka mau tunduk di bawah kekuasaan Nabi saw. Maka Abu Lubabah bermusyawarah dengan mereka; akan tetapi ia mengisyaratkan dengan tangannya kepada mereka, bahwa jika mereka tunduk maka hukumannya adalah sembelih (maut). Abu Lubabah sengaja berbuat demikian demi untuk melindungi anak-anak dan harta bendanya yang berada di antara mereka.",[["وَٱذْكُرُوٓا۟","And remember"],["إِذْ","when"],["أَنتُمْ","you"],["قَلِيلٌۭ","(were) few"],["مُّسْتَضْعَفُونَ","(and) deemed weak"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["تَخَافُونَ","fearing"],["أَن","that"],["يَتَخَطَّفَكُمُ","might do away with you"],["ٱلنَّاسُ","the men"],["فَـَٔاوَىٰكُمْ","then He sheltered you"],["وَأَيَّدَكُم","and strengthened you"],["بِنَصْرِهِۦ","with His help"],["وَرَزَقَكُم","and provided you"],["مِّنَ","of"],["ٱلطَّيِّبَـٰتِ","the good things"],["لَعَلَّكُمْ","so that you may"],["تَشْكُرُونَ","(be) thankful"]]],"1187":["(Hai orang-orang yang beriman janganlah kalian mengkhianati Allah dan rasul-Nya dan) jangan pula (kalian mengkhianati amanat-amanat kalian) yakni apa-apa yang dipercayakan kepada kalian berupa agama dan hal-hal yang lain (sedangkan kalian mengetahui).",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تَخُونُوا۟","betray"],["ٱللَّهَ","Allah"],["وَٱلرَّسُولَ","and the Messenger"],["وَتَخُونُوٓا۟","or betray"],["أَمَـٰنَـٰتِكُمْ","your trusts"],["وَأَنتُمْ","while you"],["تَعْلَمُونَ","know"]]],"1188":["(Dan ketahuilah bahwa harta kalian dan anak-anak kalian itu hanyalah sebagai cobaan) buat kalian yang menghambat kalian daripada perkara-perkara akhirat (dan sesungguhnya di sisi Allahlah pahala yang besar) maka janganlah sekali-kali kalian melewatkan pahala yang besar sehingga kalian mau berbuat khianat demi untuk mereka. Ayat berikut diturunkan berkenaan dengan tobatnya Abu Lubabah.",[["وَٱعْلَمُوٓا۟","And know"],["أَنَّمَآ","that"],["أَمْوَٰلُكُمْ","your wealth"],["وَأَوْلَـٰدُكُمْ","and your children"],["فِتْنَةٌۭ","(are) a trial"],["وَأَنَّ","And that"],["ٱللَّهَ","Allah "],["عِندَهُۥٓ","with Him"],["أَجْرٌ","(is) a reward"],["عَظِيمٌۭ","great"]]],"1189":["(Hai orang-orang yang beriman, jika kalian bertakwa kepada Allah) melalui berserah diri kepada-Nya dan cara-cara yang lain (niscaya Dia akan memberikan kepada kalian petunjuk) buat kalian sehingga kalian dapat membedakan hal-hal yang dapat membawa keselamatan dan hal-hal yang membahayakan diri kalian, sehingga kalian selamat dari hal-hal yang kalian takutkan (dan menghapuskan segala kesalahan-kesalahan dan mengampuni kalian) dosa-dosa kalian. (Dan Allah mempunyai karunia yang besar).",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe"],["إِن","If"],["تَتَّقُوا۟","you fear"],["ٱللَّهَ","Allah"],["يَجْعَل","He will grant"],["لَّكُمْ","you"],["فُرْقَانًۭا","a criterion"],["وَيُكَفِّرْ","and will remove"],["عَنكُمْ","from you"],["سَيِّـَٔاتِكُمْ","your evil deeds"],["وَيَغْفِرْ","and forgive"],["لَكُمْ ۗ","you"],["وَٱللَّهُ","And Allah"],["ذُو","(is) the Possessor"],["ٱلْفَضْلِ","(of) Bounty"],["ٱلْعَظِيمِ","the Great"]]],"1190":["(Dan) ingatlah hai Muhammad (ketika orang-orang kafir Quraisy merencanakan tipu muslihat terhadap dirimu) mereka mengadakan pertemuan di Darun Nadwah tempat mereka bermusyawarah guna mengadakan makar terhadap dirimu (untuk menangkapmu) untuk mengikatmu dan memenjarakanmu (atau membunuhmu) di mana mereka secara beramai-ramai membunuhmu (atau mengusirmu) dari Kota Mekah. (Mereka merencanakan tipu muslihat) terhadap dirimu (akan tetapi Allah menggagalkan rencana mereka dengan cara memberikan pemberitahuan kepadamu melalui wahyu-Nya akan rencana mereka dan Dia memerintahkan kamu untuk keluar terlebih dahulu. (Dan Allah sebaik-baik pembalas tipu muslihat). Dia Maha Mengetahui tentang tipu muslihat.",[["وَإِذْ","And when"],["يَمْكُرُ","plotted"],["بِكَ","against you"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["لِيُثْبِتُوكَ","that they restrain you"],["أَوْ","or"],["يَقْتُلُوكَ","kill you"],["أَوْ","or"],["يُخْرِجُوكَ ۚ","drive you out"],["وَيَمْكُرُونَ","And they were planning"],["وَيَمْكُرُ","and (also) was planning"],["ٱللَّهُ ۖ","Allah"],["وَٱللَّهُ","And Allah"],["خَيْرُ","is (the) Best"],["ٱلْمَـٰكِرِينَ","(of) the Planners"]]],"1191":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) yakni Alquran (mereka berkata, \"Sesungguhnya kami telah mendengar ayat-ayat seperti ini, kalau kami menghendaki niscaya kami dapat membacakan yang seperti ini) ucapan ini telah dikatakan oleh Nadhr bin Harits, karena ia sering berkunjung ke negeri Hairah untuk tujuan berniaga. Di sana ia membeli buku-buku tentang sejarah orang-orang Ajam, kemudian ia menceritakannya kepada penduduk kota Mekah. (Tiada lain) tak lain (hal ini) yakni Alquran (hanyalah dongeng-dongengan) cerita-cerita bohong (orang-orang dahulu.\")",[["وَإِذَا","And when"],["تُتْلَىٰ","are recited"],["عَلَيْهِمْ","to them"],["ءَايَـٰتُنَا","Our Verses"],["قَالُوا۟","they say"],["قَدْ","Verily"],["سَمِعْنَا","we have heard"],["لَوْ","if"],["نَشَآءُ","we wish"],["لَقُلْنَا","surely, we could say"],["مِثْلَ","like"],["هَـٰذَآ ۙ","this"],["إِنْ","Not"],["هَـٰذَآ","is this"],["إِلَّآ","but"],["أَسَـٰطِيرُ","tales"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"1192":["(Dan ingatlah ketika mereka/orang-orang musyrik berkata, \"Ya Allah! Jika betul hal ini) yaitu Alquran yang dibacakan oleh Muhammad (dialah yang benar) diturunkan (dari sisi Engkau, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab yang pedih.\") siksaan yang menyakitkan sekali sebagai pembalasan atas ingkar kami terhadapnya. Perkataan ini diucapkan oleh Nadhr dan lain-lainnya sebagai penghinaan dengan maksud untuk memberikan gambaran kepada orang lain seakan-akan ia benar-benar mengetahui akan kebatilan Alquran. Allah swt. telah berfirman:",[["وَإِذْ","And when"],["قَالُوا۟","they said"],["ٱللَّهُمَّ","O Allah"],["إِن","If"],["كَانَ","was"],["هَـٰذَا","this"],["هُوَ","[it]"],["ٱلْحَقَّ","the truth"],["مِنْ","[of]"],["عِندِكَ","from You"],["فَأَمْطِرْ","then (send) rain"],["عَلَيْنَا","upon us"],["حِجَارَةًۭ","(of) stones"],["مِّنَ","from"],["ٱلسَّمَآءِ","the sky"],["أَوِ","or"],["ٱئْتِنَا","bring (upon) us"],["بِعَذَابٍ","a punishment"],["أَلِيمٍۢ","painful"]]],"1193":["(Dan Allah sekali-kali tidak akan mengazab mereka) oleh sebab apa yang telah mereka minta (sedangkan kamu berada di antara mereka) karena jika azab itu turun akan menimpa semua orang tanpa kecuali. Dan tiada suatu umat pun yang diazab melainkan setelah nabi dan kaum mukminin keluar daripadanya. (Dan tidak pula Allah akan mengazab mereka, sedangkan mereka meminta ampun) karena ternyata di dalam tawaf yang mereka lakukan mereka selalu mengatakan, \"Ampunan-Mu, ampunan-Mu.\" Dan menurut suatu pendapat dikatakan bahwa orang-orang yang meminta ampunan itu adalah orang-orang lemah dari kalangan kaum mukminin yang tinggal bersama dengan orang-orang kafir sebagaimana yang telah dijelaskan oleh firman-Nya, \"Sekiranya mereka tidak bercampur-baur, tentulah Kami akan mengazab orang-orang kafir di antara mereka dengan azab yang pedih.\" (Q.S. Al-Fath 25).",[["وَمَا","But not"],["كَانَ","is"],["ٱللَّهُ","(for) Allah"],["لِيُعَذِّبَهُمْ","that He punishes them"],["وَأَنتَ","while you"],["فِيهِمْ ۚ","(are) among them"],["وَمَا","and not"],["كَانَ","is"],["ٱللَّهُ","Allah"],["مُعَذِّبَهُمْ","the One Who punishes them"],["وَهُمْ","while they"],["يَسْتَغْفِرُونَ","seek forgiveness"]]],"1194":["(Mengapa Allah tidak mengazab mereka) dengan pedang sesudah engkau dan kaum mukminin yang lemah keluar dari Mekah. Berdasarkan pendapat yang pertama, ayat ini menasakh ayat sebelumnya; dan ternyata Allah swt. mengazab mereka dalam perang Badar dan perang-perang yang lain (padahal mereka menghalangi) mencegah Nabi saw. dan kaum muslimin (untuk mendatangi Masjidilharam) yakni untuk melakukan tawaf di dalamnya (dan mereka bukanlah orang-orang yang berhak menguasainya?) seperti menurut dugaan mereka. (Tiada lain) tidak lain (orang-orang yang berhak menguasainya hanyalah orang-orang yang bertakwa tetapi kebanyakan mereka tidak mengetahui) bahwasanya tidak ada hak bagi orang-orang kafir untuk menguasai Masjidilharam.",[["وَمَا","But what"],["لَهُمْ","(is) for them"],["أَلَّا","that not"],["يُعَذِّبَهُمُ","(should) punish them"],["ٱللَّهُ","Allah"],["وَهُمْ","while they"],["يَصُدُّونَ","hinder (people)"],["عَنِ","from"],["ٱلْمَسْجِدِ","Al-Masjid"],["ٱلْحَرَامِ","Al-Haraam"],["وَمَا","while not"],["كَانُوٓا۟","they are"],["أَوْلِيَآءَهُۥٓ ۚ","its guardians"],["إِنْ","Not (can be)"],["أَوْلِيَآؤُهُۥٓ","its guardians"],["إِلَّا","except"],["ٱلْمُتَّقُونَ","the ones who fear Allah"],["وَلَـٰكِنَّ","but"],["أَكْثَرَهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1195":["(Salat mereka di sekitar Baitullah itu tiada lain hanyalah siulan) bersiul-siul (dan tepuk tangan) artinya mereka menjadikan hal-hal tersebut sebagai upacara sembahyang mereka yang dianjurkan oleh sesama mereka. (Maka rasakanlah azab) dalam perang Badar (disebabkan kekafiran kalian).",[["وَمَا","And not"],["كَانَ","was"],["صَلَاتُهُمْ","their prayer"],["عِندَ","at"],["ٱلْبَيْتِ","the House"],["إِلَّا","except"],["مُكَآءًۭ","whistling"],["وَتَصْدِيَةًۭ ۚ","and clapping"],["فَذُوقُوا۟","So taste"],["ٱلْعَذَابَ","the punishment"],["بِمَا","because"],["كُنتُمْ","you used to"],["تَكْفُرُونَ","disbelieve"]]],"1196":["Sesungguhnya orang-orang yang kafir itu menafkahkan harta mereka) di dalam memerangi Nabi saw. (untuk menghalangi orang dari jalan Allah. Mereka akan menafkahkan harta itu kemudian hal itu) pada akhirnya (menjadi sesalan bagi mereka sendiri) mereka akan merasa menyesal karena harta mereka terbuang secara percuma dan tujuan mereka tidak berhasil (kemudian mereka dikalahkan) di dunia. (Dan orang-orang yang kafir itu) dari kalangan orang-orang Quraisy (ke neraka Jahanam) kelak di akhirat (akan dikumpulkan) mereka digiring ke dalamnya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["يُنفِقُونَ","they spend"],["أَمْوَٰلَهُمْ","their wealth"],["لِيَصُدُّوا۟","to hinder (people)"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ ۚ","(of) Allah"],["فَسَيُنفِقُونَهَا","So they will spend it"],["ثُمَّ","then"],["تَكُونُ","it will be"],["عَلَيْهِمْ","for them"],["حَسْرَةًۭ","a regret"],["ثُمَّ","then"],["يُغْلَبُونَ ۗ","they will be overcome"],["وَٱلَّذِينَ","And those who"],["كَفَرُوٓا۟","disbelieve"],["إِلَىٰ","to"],["جَهَنَّمَ","Hell"],["يُحْشَرُونَ","they will be gathered"]]],"1197":["(Supaya Allah membedakan) lafal ini berkaitan dengan lafal takuunu pada ayat yang sebelumnya. Boleh dibaca tidak memakai tasydid atau memakainya; artinya memisahkan (antara golongan yang buruk) orang kafir (dan yang baik) orang mukmin (dan menjadikan golongan yang buruk itu sebagiannya di atas sebagian yang lain, kesemuanya ditumpukkan-Nya) artinya Allah mengumpulkan mereka secara bertumpuk-tumpuk, sebagian di antara mereka berada di atas sebagian yang lain (dan dimasukkan-Nya ke dalam neraka Jahanam. Mereka itulah orang-orang yang merugi).",[["لِيَمِيزَ","That may distinguish"],["ٱللَّهُ","Allah"],["ٱلْخَبِيثَ","the wicked"],["مِنَ","from"],["ٱلطَّيِّبِ","the good"],["وَيَجْعَلَ","and place"],["ٱلْخَبِيثَ","the wicked"],["بَعْضَهُۥ","some of them"],["عَلَىٰ","on"],["بَعْضٍۢ","others"],["فَيَرْكُمَهُۥ","and heap them"],["جَمِيعًۭا","all together"],["فَيَجْعَلَهُۥ","and put them"],["فِى","in"],["جَهَنَّمَ ۚ","Hell"],["أُو۟لَـٰٓئِكَ","Those "],["هُمُ","they"],["ٱلْخَـٰسِرُونَ","(are) the losers"]]],"1198":["(Katakanlah kepada orang-orang yang kafir itu,) seperti Abu Sofyan dan teman-temannya (\"Jika mereka berhenti) dari kekafirannya dan dari memerangi Nabi saw. (niscaya Allah akan mengampuni mereka tentang dosa-dosa mereka yang telah lalu) dari amal perbuatan mereka (dan jika mereka kembali lagi) untuk memerangi Nabi saw. (sesungguhnya akan berlaku terhadap mereka sunah Allah terhadap orang-orang dahulu.\") Allah akan memberlakukan sunah-Nya terhadap diri mereka, dengan cara membinasakannya, seperti yang telah Kami lakukan terhadap umat-umat terdahulu.",[["قُل","Say"],["لِّلَّذِينَ","to those who"],["كَفَرُوٓا۟","disbelieve"],["إِن","if"],["يَنتَهُوا۟","they cease"],["يُغْفَرْ","will be forgiven"],["لَهُم","for them"],["مَّا","what"],["قَدْ","[verily]"],["سَلَفَ","(is) past"],["وَإِن","But if"],["يَعُودُوا۟","they return"],["فَقَدْ","then verily"],["مَضَتْ","preceded"],["سُنَّتُ","(the) practice"],["ٱلْأَوَّلِينَ","(of) the former (people)"]]],"1199":["(Dan perangilah mereka supaya tidak ada) supaya jangan ada (fitnah) kemusyrikan (dan supaya agama itu semata-mata bagi Allah) hanya bagi Allah semata dan tidak disembah selain dari-Nya. (Jika mereka berhenti) dari kekafiran (Maka sesungguhnya Allah Maha Melihat apa yang mereka kerjakan) Dia akan membalas mereka karenanya.",[["وَقَـٰتِلُوهُمْ","And fight them"],["حَتَّىٰ","until"],["لَا","not"],["تَكُونَ","there is"],["فِتْنَةٌۭ","oppression"],["وَيَكُونَ","and is"],["ٱلدِّينُ","the religion"],["كُلُّهُۥ","all of it"],["لِلَّهِ ۚ","for Allah"],["فَإِنِ","But if"],["ٱنتَهَوْا۟","they cease"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["بِمَا","of what"],["يَعْمَلُونَ","they do"],["بَصِيرٌۭ","(is) All-Seer"]]],"1200":["(Dan jika mereka berpaling) dari keimanan (maka ketahuilah bahwasanya Allah pelindung kalian) yang akan menolong dan mengatur urusan-urusan kalian (sebaik-baik pelindung) adalah Dia (dan Dia adalah sebaik-baik penolong) yang akan menolong kalian.",[["وَإِن","And if"],["تَوَلَّوْا۟","they turn away"],["فَٱعْلَمُوٓا۟","then know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["مَوْلَىٰكُمْ ۚ","(is) your Protector"],["نِعْمَ","Excellent"],["ٱلْمَوْلَىٰ","(is) the Protector"],["وَنِعْمَ","and Excellent"],["ٱلنَّصِيرُ","(is) the Helper"]]]});